import React, { useState } from 'react';
import { CountryData } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

interface Props {
  data: CountryData[];
}

const Comparison: React.FC<Props> = ({ data }) => {
  const [selectedCodes, setSelectedCodes] = useState<string[]>(['TR', 'US', 'SG']);

  const handleToggle = (code: string) => {
    if (selectedCodes.includes(code)) {
        if(selectedCodes.length > 1) {
            setSelectedCodes(prev => prev.filter(c => c !== code));
        }
    } else {
      if (selectedCodes.length < 5) {
        setSelectedCodes(prev => [...prev, code]);
      } else {
          alert("Maksimum 5 ülke karşılaştırabilirsiniz.");
      }
    }
  };

  const selectedCountries = data.filter(c => selectedCodes.includes(c.code));

  // Prepare Radar Data (Components)
  const radarData = [
    { subject: 'Risk Alma (RTC)', fullMark: 100 },
    { subject: 'İnovasyon (ICT)', fullMark: 100 },
    { subject: 'Özerklik (IAW)', fullMark: 100 },
    { subject: 'Tutku (PIM)', fullMark: 100 },
    { subject: 'Sosyal (SCW)', fullMark: 100 },
    { subject: 'Finans (FA)', fullMark: 100 },
    { subject: 'Regülasyon (RFQ)', fullMark: 100 },
    { subject: 'Pazar (MD)', fullMark: 100 },
    { subject: 'Bilgi (KI)', fullMark: 100 },
    { subject: 'Ağlar (EN)', fullMark: 100 },
  ];

  const radarChartData = radarData.map(item => {
      const obj: any = { subject: item.subject, fullMark: 100 };
      selectedCountries.forEach(c => {
          // Map short codes to values
          let val = 0;
          if(item.subject.includes('RTC')) val = c.RTC;
          if(item.subject.includes('ICT')) val = c.ICT;
          if(item.subject.includes('IAW')) val = c.IAW;
          if(item.subject.includes('PIM')) val = c.PIM;
          if(item.subject.includes('SCW')) val = c.SCW;
          if(item.subject.includes('FA')) val = c.FA;
          if(item.subject.includes('RFQ')) val = c.RFQ;
          if(item.subject.includes('MD')) val = c.MD;
          if(item.subject.includes('KI')) val = c.KI;
          if(item.subject.includes('EN')) val = c.EN;
          obj[c.name] = val;
      });
      return obj;
  });

  const colors = ['#8884d8', '#82ca9d', '#ffc658', '#ff7300', '#00C49F'];

  return (
    <div className="space-y-6">
      {/* Selection Area */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <h3 className="font-bold mb-4">Karşılaştırılacak Ülkeler (Max 5)</h3>
        <div className="flex flex-wrap gap-2">
            {data.map(country => (
                <button
                    key={country.code}
                    onClick={() => handleToggle(country.code)}
                    className={`px-3 py-2 rounded-lg text-sm flex items-center gap-2 border transition-colors ${
                        selectedCodes.includes(country.code) 
                        ? 'bg-blue-100 border-blue-500 text-blue-800 font-medium' 
                        : 'bg-white border-gray-200 hover:bg-gray-50'
                    }`}
                >
                    <span>{country.flag}</span> {country.name}
                </button>
            ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Radar Chart */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-[500px]">
            <h3 className="font-bold mb-4 text-center">Bileşen Analizi (Radar)</h3>
            <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarChartData}>
                <PolarGrid />
                <PolarAngleAxis dataKey="subject" tick={{ fontSize: 10 }} />
                <PolarRadiusAxis angle={30} domain={[0, 100]} />
                {selectedCountries.map((country, index) => (
                    <Radar
                        key={country.code}
                        name={country.name}
                        dataKey={country.name}
                        stroke={colors[index % colors.length]}
                        fill={colors[index % colors.length]}
                        fillOpacity={0.1}
                    />
                ))}
                <Legend />
                <Tooltip />
                </RadarChart>
            </ResponsiveContainer>
          </div>

          {/* Bar Chart Summary */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-[500px]">
             <h3 className="font-bold mb-4 text-center">SEGRİ Ana Puan Karşılaştırması</h3>
             <ResponsiveContainer width="100%" height="100%">
                 <BarChart data={selectedCountries} layout="vertical" margin={{ left: 40, right: 40 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" domain={[0, 100]} />
                    <YAxis dataKey="name" type="category" width={80} />
                    <Tooltip cursor={{fill: 'transparent'}} />
                    <Legend />
                    <Bar dataKey="IES" fill="#8884d8" name="Bireysel (IES)" />
                    <Bar dataKey="EEF" fill="#82ca9d" name="Ekosistem (EEF)" />
                    <Bar dataKey="SEGRI" fill="#ff7300" name="SEGRİ" />
                 </BarChart>
             </ResponsiveContainer>
          </div>
      </div>

      {/* Detailed Table */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 overflow-x-auto">
          <table className="w-full text-sm text-left">
              <thead className="bg-gray-50 text-gray-700 uppercase">
                  <tr>
                      <th className="px-4 py-2">Bileşen</th>
                      {selectedCountries.map(c => <th key={c.code} className="px-4 py-2">{c.flag} {c.name}</th>)}
                  </tr>
              </thead>
              <tbody>
                  <tr className="border-b bg-blue-50 font-bold">
                      <td className="px-4 py-2">SEGRİ</td>
                      {selectedCountries.map(c => <td key={c.code} className="px-4 py-2 text-blue-700">{c.SEGRI.toFixed(2)}</td>)}
                  </tr>
                  <tr className="border-b">
                      <td className="px-4 py-2 font-semibold">IES (Toplam)</td>
                      {selectedCountries.map(c => <td key={c.code} className="px-4 py-2">{c.IES.toFixed(2)}</td>)}
                  </tr>
                  <tr className="border-b">
                      <td className="px-4 py-2 font-semibold">EEF (Toplam)</td>
                      {selectedCountries.map(c => <td key={c.code} className="px-4 py-2">{c.EEF.toFixed(2)}</td>)}
                  </tr>
                  {/* Rows for details */}
                  {['RTC', 'ICT', 'IAW', 'PIM', 'SCW'].map(key => (
                       <tr key={key} className="border-b hover:bg-gray-50">
                       <td className="px-4 py-2 text-gray-500">{key}</td>
                       {selectedCountries.map(c => <td key={c.code} className="px-4 py-2">{(c as any)[key]}</td>)}
                   </tr>
                  ))}
                  {['FA', 'RFQ', 'MD', 'KI', 'EN'].map(key => (
                       <tr key={key} className="border-b hover:bg-gray-50">
                       <td className="px-4 py-2 text-gray-500">{key}</td>
                       {selectedCountries.map(c => <td key={c.code} className="px-4 py-2">{(c as any)[key]}</td>)}
                   </tr>
                  ))}
              </tbody>
          </table>
      </div>
    </div>
  );
};

export default Comparison;

import React, { useState, useEffect } from 'react';
import { calculateIES, calculateEEF, calculateSEGRI, determineQuadrant, determineTypology } from '../utils';
import { COLORS } from '../constants';

const Calculator: React.FC = () => {
  const [inputs, setInputs] = useState({
    RTC: 50, ICT: 50, IAW: 50, PIM: 50, SCW: 50,
    FA: 50, RFQ: 50, MD: 50, KI: 50, EN: 50
  });

  const [results, setResults] = useState({
      IES: 0, EEF: 0, SEGRI: 0, quadrant: '', typology: ''
  });

  useEffect(() => {
    const ies = calculateIES(inputs.RTC, inputs.ICT, inputs.IAW, inputs.PIM, inputs.SCW);
    const eef = calculateEEF(inputs.FA, inputs.RFQ, inputs.MD, inputs.KI, inputs.EN);
    const segri = calculateSEGRI(ies, eef);
    const quad = determineQuadrant(ies, eef);
    const type = determineTypology(inputs.RTC, inputs.ICT, inputs.IAW, inputs.PIM, inputs.SCW);
    setResults({ IES: ies, EEF: eef, SEGRI: segri, quadrant: quad, typology: type });
  }, [inputs]);

  const handleChange = (key: string, val: string) => {
    setInputs(prev => ({ ...prev, [key]: Number(val) }));
  };

  const getQuadColor = (q: string) => {
