import React, { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { fetchSectorWeights } from '../api';
import { CountryData, SectorName } from '../types';
import { calculateRiskScore } from '../utils';
import { Loader2, TrendingUp, AlertTriangle, ShieldCheck, Zap } from 'lucide-react';

interface Props {
  countries: CountryData[];
}

const RiskAnalysis: React.FC<Props> = ({ countries }) => {
  const [selectedCountryCode, setSelectedCountryCode] = useState<string>(countries[0]?.code || '');
  const [selectedSector, setSelectedSector] = useState<SectorName>("Teknoloji");

  const { data: sectorWeights, isLoading, isError } = useQuery({
    queryKey: ['sectorWeights'],
    queryFn: fetchSectorWeights,
  });

  // Risk Inputs
  const [srfInputs, setSrfInputs] = useState({
    TRF: 50, TZR: 50, JRF: 50, ESG: 50, ORF: 50
  });

  // Blind Spot Inputs
  const [knaInputs, setKnaInputs] = useState({
    OKN: 50, SKN: 50, TKN: 50, KKN: 50
  });

  const [srkaResult, setSrkaResult] = useState(0);

  const activeCountry = countries.find(c => c.code === selectedCountryCode) || countries[0];
  const activeWeights = sectorWeights ? sectorWeights[selectedSector] : null;

  // KNA Weights are fixed in prompt (30, 25, 25, 20)
  const knaWeights = { OKN: 0.30, SKN: 0.25, TKN: 0.25, KKN: 0.20 };

  useEffect(() => {
    if (!activeCountry || !activeWeights) return;

    // 1. Calculate SRF (Sectoral Risk Factor)
    const srfScore = calculateRiskScore(srfInputs, activeWeights);

    // 2. Calculate KNA
    const knaScore = calculateRiskScore(knaInputs, knaWeights);

    // 3. SEGRİ-SRKA = (0.40 * SEGRİ) + (0.35 * SRF) + (0.25 * KNA)
    const finalScore = (0.40 * activeCountry.SEGRI) + (0.35 * srfScore) + (0.25 * knaScore);
    setSrkaResult(finalScore);

  }, [srfInputs, knaInputs, activeCountry, activeWeights]);

  const handleSrfChange = (key: string, val: string) => setSrfInputs(p => ({...p, [key]: parseInt(val)}));
  const handleKnaChange = (key: string, val: string) => setKnaInputs(p => ({...p, [key]: parseInt(val)}));

  const getRiskQuadrantInfo = (segri: number, riskMgmt: number) => {
      // Y-Axis: SEGRİ (Threshold 60)
      // X-Axis: Risk Mgmt (Threshold 65)

      if(segri >= 60 && riskMgmt >= 65) return { 
          id: 'leader',
          name: "LİDER DAYANIKLI", 
          icon: <TrendingUp size={24} />,
          colorClass: "bg-green-100 text-green-800 border-green-300",
          desc: "Sürdürülebilir büyüme",
          strategy: "Mevcut risk yönetimini koruyarak pazar liderliğini sürdür."
      };
      if(segri >= 60 && riskMgmt < 65) return { 
          id: 'opportunist',
          name: "FIRSATÇI BÜYÜMECİ", 
          icon: <Zap size={24} />,
          colorClass: "bg-blue-100 text-blue-800 border-blue-300",
          desc: "Risk yönetimi altyapısı kur",
          strategy: "Büyüme hızını korurken kurumsal risk yapılarını acilen oluştur."
      };
      if(segri < 60 && riskMgmt >= 65) return { 
          id: 'protector',
          name: "KORUYUCU DAYANIKLI", 
          icon: <ShieldCheck size={24} />,
          colorClass: "bg-purple-100 text-purple-800 border-purple-300",
          desc: "Girişimcilik kapasitesini artır",
          strategy: "Güçlü yapıyı koruyarak inovasyon ve girişimcilik kaslarını geliştir."
      };
      return { 
          id: 'risky',
          name: "RİSKLİ KIRILGAN", 
          icon: <AlertTriangle size={24} />,
          colorClass: "bg-red-100 text-red-800 border-red-300",
          desc: "Acil transformasyon",
          strategy: "Kriz yönetimi ilan et ve köklü yapısal dönüşüm başlat."
      };
  };

  if (isLoading) {
      return (
          <div className="flex flex-col items-center justify-center h-96 text-gray-500">
              <Loader2 className="animate-spin mb-2" />
              <p>Risk parametreleri yükleniyor...</p>
          </div>
      );
  }

  if (isError || !activeWeights) {
      return <div className="text-red-500 p-4">Veri yüklenemedi.</div>;
  }

  const riskMgmtScore = ((0.35 * calculateRiskScore(srfInputs, activeWeights)) + (0.25 * calculateRiskScore(knaInputs, knaWeights))) / 0.60;
  const quadrantInfo = getRiskQuadrantInfo(activeCountry.SEGRI, riskMgmtScore);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-12">
        <div className="lg:col-span-8 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-medium mb-1">Ülke Seçimi</label>
                        <select 
                            className="w-full p-2 border rounded"
                            value={selectedCountryCode}
                            onChange={(e) => setSelectedCountryCode(e.target.value)}
                        >
                            {countries.map(c => <option key={c.code} value={c.code}>{c.flag} {c.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Sektör Seçimi</label>
                        <select 
                            className="w-full p-2 border rounded"
                            value={selectedSector}
                            onChange={(e) => setSelectedSector(e.target.value as SectorName)}
                        >
                            {sectorWeights && Object.keys(sectorWeights).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* SRF Inputs */}
                    <div>
                        <h4 className="font-bold text-gray-700 mb-3 border-b pb-2 flex justify-between">
                            <span>SRF: Sektörel Risk Yönetimi</span>
                            <span className="text-sm bg-gray-100 px-2 py-0.5 rounded text-gray-600">%35</span>
                        </h4>
                        <p className="text-xs text-gray-500 mb-4">Puan ne kadar yüksekse, risk yönetimi o kadar güçlüdür.</p>
                        {Object.entries(srfInputs).map(([key, val]) => (
                            <div key={key} className="mb-3">
                                <div className="flex justify-between text-sm mb-1">
                                    <span>{key} (Ağırlık: %{(activeWeights as any)[key] * 100})</span>
                                    <span className="font-bold">{val}</span>
                                </div>
                                <input type="range" min="0" max="100" value={val} onChange={(e) => handleSrfChange(key, e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                            </div>
                        ))}
                    </div>

                    {/* KNA Inputs */}
                    <div>
                         <h4 className="font-bold text-gray-700 mb-3 border-b pb-2 flex justify-between">
                            <span>KNA: Kör Nokta Farkındalığı</span>
                            <span className="text-sm bg-gray-100 px-2 py-0.5 rounded text-gray-600">%25</span>
                        </h4>
                        <p className="text-xs text-gray-500 mb-4">Puan ne kadar yüksekse, kör noktalar o kadar azdır (farkındalık yüksek).</p>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>OKN: Organizasyonel (%30)</span><span className="font-bold">{knaInputs.OKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.OKN} onChange={(e) => handleKnaChange('OKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>SKN: Sektörel (%25)</span><span className="font-bold">{knaInputs.SKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.SKN} onChange={(e) => handleKnaChange('SKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>TKN: Teknolojik (%25)</span><span className="font-bold">{knaInputs.TKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.TKN} onChange={(e) => handleKnaChange('TKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                         <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>KKN: Kültürel (%20)</span><span className="font-bold">{knaInputs.KKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.KKN} onChange={(e) => handleKnaChange('KKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="lg:col-span-4 space-y-4">
            {/* Score Card */}
            <div className="bg-gray-900 text-white p-6 rounded-xl shadow-lg flex flex-col justify-center items-center text-center relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                    <ShieldCheck size={100} />
                </div>
                <h3 className="text-xl font-bold mb-2 z-10">SEGRİ-SRKA Skoru</h3>
                <div className="text-6xl font-bold text-yellow-400 mb-2 z-10">{srkaResult.toFixed(1)}</div>
                <div className="text-sm opacity-70 mb-6 z-10">Genişletilmiş Risk Çerçevesi</div>

                <div className={`w-full p-4 rounded-lg mb-4 border-2 ${quadrantInfo.colorClass}`}>
                    <div className="flex items-center justify-center gap-2 mb-1">
                        {quadrantInfo.icon}
                        <h4 className="text-lg font-black uppercase">{quadrantInfo.name}</h4>
                    </div>
                    <p className="text-xs font-semibold opacity-80">{quadrantInfo.desc}</p>
                    <p className="text-xs mt-2 italic bg-white/50 p-2 rounded text-gray-800">
                        "{quadrantInfo.strategy}"
                    </p>
                </div>

                <div className="text-xs text-left w-full space-y-1 opacity-70 bg-gray-800 p-3 rounded">
                    <div className="flex justify-between"><span>SEGRİ (%40):</span> <span className="text-yellow-400">{activeCountry.SEGRI.toFixed(1)}</span></div>
                    <div className="flex justify-between"><span>SRF (%35):</span> <span className="text-blue-400">{calculateRiskScore(srfInputs, activeWeights).toFixed(1)}</span></div>
                    <div className="flex justify-between"><span>KNA (%25):</span> <span className="text-green-400">{calculateRiskScore(knaInputs, knaWeights).toFixed(1)}</span></div>
                </div>
            </div>

            {/* Matrix Visualization */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                <h4 className="font-bold text-gray-700 text-sm mb-3">Risk Matrisi Konumu</h4>
                <div className="grid grid-cols-2 gap-2 text-xs">
                     {/* Opportunist: High SEGRİ, Low Risk */}
                    <div className={`p-2 rounded border transition-all ${quadrantInfo.id === 'opportunist' ? 'bg-blue-100 border-blue-500 ring-1 ring-blue-500 opacity-100 scale-105 shadow-md z-10' : 'bg-gray-50 border-gray-200 opacity-60 grayscale'}`}>
                        <div className="font-bold text-blue-800">FIRSATÇI</div>
                        <div className="text-[10px] text-blue-600">Yüksek SEGRİ<br/>Düşük Risk Ynt.</div>
                    </div>
                    {/* Leader: High SEGRİ, High Risk */}
                    <div className={`p-2 rounded border transition-all ${quadrantInfo.id === 'leader' ? 'bg-green-100 border-green-500 ring-1 ring-green-500 opacity-100 scale-105 shadow-md z-10' : 'bg-gray-50 border-gray-200 opacity-60 grayscale'}`}>
                        <div className="font-bold text-green-800">LİDER</div>
                        <div className="text-[10px] text-green-600">Yüksek SEGRİ<br/>Yüksek Risk Ynt.</div>
                    </div>
                    {/* Risky: Low SEGRİ, Low Risk */}
                    <div className={`p-2 rounded border transition-all ${quadrantInfo.id === 'risky' ? 'bg-red-100 border-red-500 ring-1 ring-red-500 opacity-100 scale-105 shadow-md z-10' : 'bg-gray-50 border-gray-200 opacity-60 grayscale'}`}>
                        <div className="font-bold text-red-800">RİSKLİ</div>
                        <div className="text-[10px] text-red-600">Düşük SEGRİ<br/>Düşük Risk Ynt.</div>
                    </div>
                    {/* Protector: Low SEGRİ, High Risk */}
                    <div className={`p-2 rounded border transition-all ${quadrantInfo.id === 'protector' ? 'bg-purple-100 border-purple-500 ring-1 ring-purple-500 opacity-100 scale-105 shadow-md z-10' : 'bg-gray-50 border-gray-200 opacity-60 grayscale'}`}>
                        <div className="font-bold text-purple-800">KORUYUCU</div>
                        <div className="text-[10px] text-purple-600">Düşük SEGRİ<br/>Yüksek Risk Ynt.</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

