import React, { useState, useEffect } from 'react';
import { useCountries } from '../hooks';
import { LoadingState, ErrorState } from './Common';
import { GoogleGenAI } from "@google/genai";
import { Loader2, Sparkles, Search, ExternalLink, AlertCircle, Bot } from 'lucide-react';

const DeepAnalysis: React.FC = () => {
  const { data, isLoading: isDataLoading, isError, error: dataError } = useCountries();
  const [selectedCode, setSelectedCode] = useState<string>('');
  const [analysis, setAnalysis] = useState<string>('');
  const [groundingChunks, setGroundingChunks] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Set default selection when data loads
  useEffect(() => {
    if (data && data.length > 0 && !selectedCode) {
      setSelectedCode(data[0].code);
    }
  }, [data, selectedCode]);

  if (isDataLoading) return <LoadingState />;
  if (isError) return <ErrorState error={dataError} />;
  if (!data) return null;

  const activeCountry = data.find(c => c.code === selectedCode);

  const handleAnalyze = async () => {
    if (!process.env.API_KEY) {
        setError("API Anahtarı bulunamadı. Lütfen ortam değişkenlerini kontrol edin.");
        return;
    }

    setLoading(true);
    setError(null);
    setAnalysis('');
    setGroundingChunks([]);

    if (!activeCountry) return;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        Sen uzman bir girişimcilik ekosistemi stratejistisin.
        Aşağıdaki SEGRİ (Selçuk Ergin Girişimcilik Ruhu İndeksi) verilerini analiz et ve Google Arama sonuçlarını kullanarak bu verileri güncel gelişmelerle zenginleştir (Grounding).

        Analiz Edilecek Ülke: ${activeCountry.name}

        SEGRİ Metrikleri:
        - SEGRİ Skoru: ${activeCountry.SEGRI.toFixed(2)} (Genel Performans)
        - Kadran: ${activeCountry.quadrant} (Konum)
        - Tipoloji: ${activeCountry.typology} (Karakteristik)

        Alt Bileşenler:
        1. Bireysel Ruh (IES): ${activeCountry.IES.toFixed(2)}
           - Risk Alma (RTC): ${activeCountry.RTC}
           - İnovasyon (ICT): ${activeCountry.ICT}
           - Özerklik (IAW): ${activeCountry.IAW}
           - Motivasyon (PIM): ${activeCountry.PIM}
           - Sosyal (SCW): ${activeCountry.SCW}
        2. Ekosistem (EEF): ${activeCountry.EEF.toFixed(2)}
           - Finans (FA): ${activeCountry.FA}
           - Regülasyon (RFQ): ${activeCountry.RFQ}
           - Pazar (MD): ${activeCountry.MD}
           - Bilgi (KI): ${activeCountry.KI}
           - Ağlar (EN): ${activeCountry.EN}

        Lütfen detaylı bir "Deep Dive" analizi yap:
        1. **Kök Neden Analizi**: Puanlar neden böyle? (Google aramaları ile destekle)
        2. **Kör Noktalar**: Verilerin gösterdiği ancak gözden kaçabilecek riskler neler?
        3. **Ekosistem Sinyalleri**: Ülkeden son girişimcilik haberleri bu verileri doğruluyor mu?
        4. **Eylem Planı**: ${activeCountry.quadrant} kadranındaki bu ülke için somut 3 stratejik öneri.

        Format: Markdown stili kullan (Bold başlıklar, listeler).
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        }
      });

      setAnalysis(response.text || "Analiz oluşturulamadı.");

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
        setGroundingChunks(response.candidates[0].groundingMetadata.groundingChunks);
      }

    } catch (err) {
      console.error(err);
      setError(err instanceof Error ? err.message : "Analiz sırasında bir hata oluştu.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-12">
      {/* Control Panel */}
      <div className="lg:col-span-4 space-y-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3 mb-6">
                <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
                    <Bot size={24} />
                </div>
                <div>
                    <h2 className="text-lg font-bold text-gray-900">Yapay Zeka Analizi</h2>
                    <p className="text-xs text-gray-500">Gemini 3.0 & Google Search</p>
                </div>
            </div>

            <div className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Ülke Seçimi</label>
                    <select 
                        className="w-full p-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                        value={selectedCode}
                        onChange={(e) => setSelectedCode(e.target.value)}
                    >
                        {data.map(c => (
                            <option key={c.code} value={c.code}>{c.flag} {c.name}</option>
                        ))}
                    </select>
                </div>

                {activeCountry && (
                    <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 text-sm space-y-2">
                        <div className="flex justify-between">
                            <span className="text-gray-500">SEGRİ</span>
                            <span className="font-bold text-gray-900">{activeCountry.SEGRI.toFixed(1)}</span>
                        </div>
                        <div className="flex justify-between">
                            <span className="text-gray-500">Kadran</span>
                            <span className="font-medium text-indigo-600">{activeCountry.quadrant}</span>
                        </div>
                        <div className="flex justify-between">
                            <span className="text-gray-500">Tipoloji</span>
                            <span className="font-medium text-purple-600">{activeCountry.typology}</span>
                        </div>
                    </div>
                )}

                <button
                    onClick={handleAnalyze}
                    disabled={loading}
                    className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm hover:shadow"
                >
                    {loading ? (
                        <>
                            <Loader2 className="animate-spin" size={20} />
                            Analiz Ediliyor...
                        </>
                    ) : (
                        <>
                            <Sparkles size={20} />
                            Deep Deep Analiz Yap
                        </>
                    )}
                </button>
            </div>
        </div>

        {/* Info Card */}
        <div className="bg-blue-50 p-6 rounded-xl border border-blue-100">
            <h4 className="font-bold text-blue-800 mb-2 flex items-center gap-2">
                <Search size={16} /> Deep Dive Nedir?
            </h4>
            <p className="text-sm text-blue-700 leading-relaxed">
                Bu modül, seçilen ülkenin SEGRİ verilerini Google'ın güncel arama sonuçlarıyla birleştirerek derinlemesine bir analiz sunar. Yapay zeka, sayısal verilerin arkasındaki reel dünya hikayesini ortaya çıkarır.
            </p>
        </div>
      </div>

      {/* Results Panel */}
      <div className="lg:col-span-8">
        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 min-h-[600px]">
            {error && (
                <div className="bg-red-50 text-red-700 p-4 rounded-lg mb-6 flex items-start gap-3 border border-red-100">
                    <AlertCircle className="shrink-0 mt-0.5" size={20} />
                    <div>
                        <p className="font-bold">Hata Oluştu</p>
                        <p className="text-sm">{error}</p>
                    </div>
                </div>
            )}

            {!analysis && !loading && !error && (
                <div className="h-full flex flex-col items-center justify-center text-gray-400 text-center p-12">
                    <Bot size={64} className="mb-4 opacity-20" />
                    <h3 className="text-lg font-medium text-gray-500">Analiz Bekleniyor</h3>
                    <p className="max-w-md mt-2">Sol taraftan bir ülke seçin ve "Deep Deep Analiz Yap" butonuna tıklayarak Gemini 3.0 destekli detaylı raporu oluşturun.</p>
                </div>
            )}

            {loading && (
                 <div className="h-full flex flex-col items-center justify-center text-indigo-600 p-12">
                    <Loader2 size={48} className="animate-spin mb-4" />
                    <h3 className="text-lg font-medium">Veriler İşleniyor</h3>
                    <p className="text-gray-500 text-sm mt-2">Google Search ile güncel veriler taranıyor...</p>
                 </div>
            )}

            {analysis && (
                <div className="animate-in fade-in duration-500">
                    <div className="flex items-center gap-2 text-sm text-gray-500 mb-6 border-b pb-4">
                        <Sparkles size={16} className="text-indigo-500" />
                        <span>Gemini 3.0 Analizi</span>
                        <span className="mx-2">•</span>
                        <span>{new Date().toLocaleDateString('tr-TR')}</span>
                    </div>

                    <div className="whitespace-pre-wrap text-gray-800 leading-relaxed text-base space-y-4">
                        {analysis}
                    </div>

                    {groundingChunks.length > 0 && (
                        <div className="mt-8 pt-6 border-t border-gray-100">
                            <h4 className="text-sm font-bold text-gray-700 mb-3 flex items-center gap-2">
                                <Search size={14} /> Kaynaklar (Google Grounding)
                            </h4>
                            <div className="grid grid-cols-1 gap-2">
                                {groundingChunks.map((chunk, idx) => {
                                    if (chunk.web?.uri) {
                                        return (
                                            <a 
                                                key={idx} 
                                                href={chunk.web.uri} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="flex items-center gap-3 p-3 rounded-lg bg-gray-50 hover:bg-gray-100 text-sm text-blue-700 transition-colors border border-gray-100 hover:border-blue-200"
                                            >
                                                <ExternalLink size={14} className="shrink-0 text-gray-400" />
                                                <span className="truncate font-medium">{chunk.web.title || chunk.web.uri}</span>
                                            </a>
                                        );
                                    }
                                    return null;
                                })}
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default DeepAnalysis;

import React, { useState, useEffect } from 'react';
import { useSectorWeights, useCountries } from '../hooks';
import { LoadingState, ErrorState } from './Common';
import { SectorName } from '../types';
import { calculateRiskScore } from '../utils';
import { TrendingUp, AlertTriangle, ShieldCheck, Zap } from 'lucide-react';

const RiskAnalysis: React.FC = () => {
  const { data: countries, isLoading: isCountriesLoading, isError: isCountriesError, error: countriesError } = useCountries();
  const { data: sectorWeights, isLoading: isWeightsLoading, isError: isWeightsError, error: weightsError } = useSectorWeights();

  const [selectedCountryCode, setSelectedCountryCode] = useState<string>('');
  const [selectedSector, setSelectedSector] = useState<SectorName>("Teknoloji");

  // Risk Inputs
  const [srfInputs, setSrfInputs] = useState({
    TRF: 50, TZR: 50, JRF: 50, ESG: 50, ORF: 50
  });

  // Blind Spot Inputs
  const [knaInputs, setKnaInputs] = useState({
    OKN: 50, SKN: 50, TKN: 50, KKN: 50
  });

  const [srkaResult, setSrkaResult] = useState(0);

  // Initial selection effect
  useEffect(() => {
    if (countries && countries.length > 0 && !selectedCountryCode) {
      setSelectedCountryCode(countries[0].code);
    }
  }, [countries, selectedCountryCode]);

  const activeCountry = countries?.find(c => c.code === selectedCountryCode);
  const activeWeights = sectorWeights ? sectorWeights[selectedSector] : null;

  // KNA Weights are fixed in prompt (30, 25, 25, 20)
  const knaWeights = { OKN: 0.30, SKN: 0.25, TKN: 0.25, KKN: 0.20 };

  useEffect(() => {
    if (!activeCountry || !activeWeights) return;

    // 1. Calculate SRF (Sectoral Risk Factor)
    const srfScore = calculateRiskScore(srfInputs, activeWeights);

    // 2. Calculate KNA
    const knaScore = calculateRiskScore(knaInputs, knaWeights);

    // 3. SEGRİ-SRKA = (0.40 * SEGRİ) + (0.35 * SRF) + (0.25 * KNA)
    const finalScore = (0.40 * activeCountry.SEGRI) + (0.35 * srfScore) + (0.25 * knaScore);
    setSrkaResult(finalScore);

  }, [srfInputs, knaInputs, activeCountry, activeWeights]);

  const handleSrfChange = (key: string, val: string) => setSrfInputs(p => ({...p, [key]: parseInt(val)}));
  const handleKnaChange = (key: string, val: string) => setKnaInputs(p => ({...p, [key]: parseInt(val)}));

  const getRiskQuadrantInfo = (segri: number, riskMgmt: number) => {
      // Y-Axis: SEGRİ (Threshold 60)
      // X-Axis: Risk Mgmt (Threshold 65)

      if(segri >= 60 && riskMgmt >= 65) return { 
          id: 'leader',
          name: "LİDER DAYANIKLI", 
          icon: <TrendingUp size={24} />,
          colorClass: "bg-green-100 text-green-800 border-green-300",
          desc: "Sürdürülebilir büyüme",
          strategy: "Mevcut risk yönetimini koruyarak pazar liderliğini sürdür."
      };
      if(segri >= 60 && riskMgmt < 65) return { 
          id: 'opportunist',
          name: "FIRSATÇI BÜYÜMECİ", 
          icon: <Zap size={24} />,
          colorClass: "bg-blue-100 text-blue-800 border-blue-300",
          desc: "Risk yönetimi altyapısı kur",
          strategy: "Büyüme hızını korurken kurumsal risk yapılarını acilen oluştur."
      };
      if(segri < 60 && riskMgmt >= 65) return { 
          id: 'protector',
          name: "KORUYUCU DAYANIKLI", 
          icon: <ShieldCheck size={24} />,
          colorClass: "bg-purple-100 text-purple-800 border-purple-300",
          desc: "Girişimcilik kapasitesini artır",
          strategy: "Güçlü yapıyı koruyarak inovasyon ve girişimcilik kaslarını geliştir."
      };
      return { 
          id: 'risky',
          name: "RİSKLİ KIRILGAN", 
          icon: <AlertTriangle size={24} />,
          colorClass: "bg-red-100 text-red-800 border-red-300",
          desc: "Acil transformasyon",
          strategy: "Kriz yönetimi ilan et ve köklü yapısal dönüşüm başlat."
      };
  };

  if (isCountriesLoading || isWeightsLoading) return <LoadingState />;
  if (isCountriesError) return <ErrorState error={countriesError} />;
  if (isWeightsError) return <ErrorState error={weightsError} />;
  if (!countries || !sectorWeights || !activeCountry || !activeWeights) return null;

  const riskMgmtScore = ((0.35 * calculateRiskScore(srfInputs, activeWeights)) + (0.25 * calculateRiskScore(knaInputs, knaWeights))) / 0.60;
  const quadrantInfo = getRiskQuadrantInfo(activeCountry.SEGRI, riskMgmtScore);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-12">
        <div className="lg:col-span-8 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-medium mb-1">Ülke Seçimi</label>
                        <select 
                            className="w-full p-2 border rounded"
                            value={selectedCountryCode}
                            onChange={(e) => setSelectedCountryCode(e.target.value)}
                        >
                            {countries.map(c => <option key={c.code} value={c.code}>{c.flag} {c.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Sektör Seçimi</label>
                        <select 
                            className="w-full p-2 border rounded"
                            value={selectedSector}
                            onChange={(e) => setSelectedSector(e.target.value as SectorName)}
                        >
                            {Object.keys(sectorWeights).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* SRF Inputs */}
                    <div>
                        <h4 className="font-bold text-gray-700 mb-3 border-b pb-2 flex justify-between">
                            <span>SRF: Sektörel Risk Yönetimi</span>
                            <span className="text-sm bg-gray-100 px-2 py-0.5 rounded text-gray-600">%35</span>
                        </h4>
                        <p className="text-xs text-gray-500 mb-4">Puan ne kadar yüksekse, risk yönetimi o kadar güçlüdür.</p>
                        {Object.entries(srfInputs).map(([key, val]) => (
                            <div key={key} className="mb-3">
                                <div className="flex justify-between text-sm mb-1">
                                    <span>{key} (Ağırlık: %{(activeWeights as any)[key] * 100})</span>
                                    <span className="font-bold">{val}</span>
                                </div>
                                <input type="range" min="0" max="100" value={val} onChange={(e) => handleSrfChange(key, e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                            </div>
                        ))}
                    </div>

                    {/* KNA Inputs */}
                    <div>
                         <h4 className="font-bold text-gray-700 mb-3 border-b pb-2 flex justify-between">
                            <span>KNA: Kör Nokta Farkındalığı</span>
                            <span className="text-sm bg-gray-100 px-2 py-0.5 rounded text-gray-600">%25</span>
                        </h4>
                        <p className="text-xs text-gray-500 mb-4">Puan ne kadar yüksekse, kör noktalar o kadar azdır (farkındalık yüksek).</p>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>OKN: Organizasyonel (%30)</span><span className="font-bold">{knaInputs.OKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.OKN} onChange={(e) => handleKnaChange('OKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>SKN: Sektörel (%25)</span><span className="font-bold">{knaInputs.SKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.SKN} onChange={(e) => handleKnaChange('SKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>TKN: Teknolojik (%25)</span><span className="font-bold">{knaInputs.TKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.TKN} onChange={(e) => handleKnaChange('TKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                         <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>KKN: Kültürel (%20)</span><span className="font-bold">{knaInputs.KKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.KKN} onChange={(e) => handleKnaChange('KKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" />
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="lg:col-span-4 space-y-4">
            {/* Score Card */}
            <div className="bg-gray-900 text-white p-6 rounded-xl shadow-lg flex flex-col justify-center items-center text-center relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                    <ShieldCheck size={100} />
                </div>
                <h3 className="text-xl font-bold mb-2 z-10">SEGRİ-SRKA Skoru</h3>
                <div className="text-6xl font-bold text-yellow-400 mb-2 z-10">{srkaResult.toFixed(1)}</div>
                <div className="text-sm opacity-70 mb-6 z-10">Genişletilmiş Risk Çerçevesi</div>

                <div className={`w-full p-4 rounded-lg mb-4 border-2 ${quadrantInfo.colorClass}`}>
