// Simple Markdown Renderer Component
const SimpleMarkdown = ({ text }: { text: string }) => {
    const lines = text.split('\n');
    return (
      <div className="space-y-4 text-gray-800 leading-relaxed font-sans">
        {lines.map((line, i) => {
          // Headers
          if (line.startsWith('### ')) {
            return <h3 key={i} className="text-lg font-bold text-indigo-800 mt-6 mb-2 flex items-center gap-2"><ChevronRight size={16} className="text-indigo-400" />{line.replace('### ', '')}</h3>;
          }
          if (line.startsWith('## ')) {
            return <h2 key={i} className="text-xl font-bold text-gray-900 mt-8 mb-3 border-b border-gray-200 pb-2">{line.replace('## ', '')}</h2>;
          }
          if (line.startsWith('# ')) {
            return <h1 key={i} className="text-2xl font-bold text-gray-900 mt-8 mb-4">{line.replace('# ', '')}</h1>;
          }

          // List items
          if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
            return (
               <div key={i} className="flex gap-3 ml-2 group">
                  <span className="text-indigo-400 mt-1.5 group-hover:text-indigo-600 transition-colors">•</span>
                  <span className="flex-1 text-gray-700">{parseBold(line.replace(/^[\-\*] /, ''))}</span>
               </div>
            );
          }

          // Numbered lists
          if (/^\d+\.\s/.test(line.trim())) {
               return (
               <div key={i} className="flex gap-3 ml-2">
                  <span className="font-bold text-indigo-600 min-w-[1.5rem]">{line.match(/^\d+\./)?.[0]}</span>
                  <span className="flex-1 text-gray-700">{parseBold(line.replace(/^\d+\.\s/, ''))}</span>
               </div>
            );
          }

          // Empty lines
          if (!line.trim()) return <div key={i} className="h-2"></div>;

          // Regular paragraph
          return <p key={i} className="text-gray-700">{parseBold(line)}</p>;
        })}
      </div>
    );
  };

  const parseBold = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={index} className="font-bold text-gray-900 bg-gray-50/50 px-0.5 rounded">{part.slice(2, -2)}</strong>;
      }
      return part;
    });
  };

export default DeepAnalysis;

import React, { useState, useEffect } from 'react';
