import React from 'react';
import ReactDOM from 'react-dom/client';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // 5 minutes
      gcTime: 1000 * 60 * 10, // 10 minutes
      refetchOnWindowFocus: true, // Enabled for background updates
      retry: 1,
    },
  },
});

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </React.StrictMode>
);

import { useQuery, UseQueryOptions } from '@tanstack/react-query';
import { fetchCountries, fetchSectorWeights } from './api';
import { CountryData, SectorName, SectorRiskWeights } from './types';

export const useCountries = <T = CountryData[]>(
  options?: Omit<UseQueryOptions<CountryData[], Error, T>, 'queryKey' | 'queryFn'>
) => {
  return useQuery({
    queryKey: ['countries'],
    queryFn: fetchCountries,
    ...options,
  });
};

export const useSectorWeights = () => {
  return useQuery({
    queryKey: ['sectorWeights'],
    queryFn: fetchSectorWeights,
  });
};

import React from 'react';
import { useCountries } from '../hooks';
import { LoadingState, ErrorState } from './Common';
import { COLORS } from '../constants';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, PieChart, Pie, Cell } from 'recharts';
import { Map, TrendingUp, Users, Activity } from 'lucide-react';
import { CountryData } from '../types';

const Overview: React.FC = () => {
  // Use selector to get only top 5 countries sorted by SEGRI
  const { 
    data: topCountries, 
    isLoading: isLoadingTop, 
    isError: isErrorTop, 
    error: errorTop 
  } = useCountries<CountryData[]>({
    select: (data) => [...data].sort((a, b) => b.SEGRI - a.SEGRI).slice(0, 5)
  });

  // Use selector to compute quadrant counts
  const { 
    data: pieData, 
    isLoading: isLoadingQuad, 
    isError: isErrorQuad, 
    error: errorQuad 
  } = useCountries<{name: string, value: number}[]>({
    select: (data) => {
      const counts = data.reduce((acc, curr) => {
        acc[curr.quadrant] = (acc[curr.quadrant] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);

      return Object.keys(counts).map(key => ({
        name: key,
        value: counts[key]
      }));
    }
  });

  if (isLoadingTop || isLoadingQuad) return <LoadingState />;
  if (isErrorTop) return <ErrorState error={errorTop} />;
  if (isErrorQuad) return <ErrorState error={errorQuad} />;
  if (!topCountries || !pieData) return null;

  const getQuadColor = (name: string) => {
    if (name === "Iron Man") return COLORS.ironMan;
    if (name === "Captain America") return COLORS.captainAmerica;
    if (name === "Black Panther") return COLORS.blackPanther;
    return COLORS.spiderMan;
  };

  return (
    <div className="space-y-6">
      {/* Intro Card */}
