                      {typologies.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
              </div>
          </div>

          <div className="overflow-x-auto">
              <table className="w-full text-sm">
                  <thead className="bg-gray-50">
                      <tr>
                          <th className="px-4 py-3 border-b text-left text-xs font-bold text-gray-500 uppercase w-10">
                              Seç
                          </th>
                          <SortHeader label="Ülke" k="name" />
                          <SortHeader label="SEGRİ" k="SEGRI" />
                          <SortHeader label="GEM" k="GEM" />
                          <SortHeader label="IES" k="IES" />
                          <SortHeader label="EEF" k="EEF" />

