                          <SortHeader label="RTC" k="RTC" />
                          <SortHeader label="ICT" k="ICT" />
                          <SortHeader label="IAW" k="IAW" />
                          <SortHeader label="PIM" k="PIM" />
                          <SortHeader label="SCW" k="SCW" />

                          {/* EEF Components */}
                          <SortHeader label="FA" k="FA" />
                          <SortHeader label="RFQ" k="RFQ" />
                          <SortHeader label="MD" k="MD" />
                          <SortHeader label="KI" k="KI" />
                          <SortHeader label="EN" k="EN" />

                          <SortHeader label="Kadran" k="quadrant" />
                          <SortHeader label="Tipoloji" k="typology" />
