                          const isSelected = selectedCodes.includes(country.code);
                          return (
                              <tr key={country.code} className={`hover:bg-blue-50/50 transition-colors ${isSelected ? 'bg-blue-50/30' : ''}`}>
                                  <td className="px-4 py-3 text-center">
                                      <button 
                                        onClick={() => handleToggle(country.code)}
                                        className={`transition-colors ${isSelected ? 'text-blue-600' : 'text-gray-300 hover:text-gray-500'}`}
                                      >
                                          {isSelected ? <CheckSquare size={20} /> : <Square size={20} />}
                                      </button>
                                  </td>
                                  <td className="px-4 py-3 font-medium text-gray-900 whitespace-nowrap flex items-center gap-2">
                                      <span className="text-xl">{country.flag}</span> {country.name}
                                  </td>
                                  <td className="px-4 py-3 font-bold text-blue-600">{country.SEGRI.toFixed(2)}</td>
                                  <td className="px-4 py-3 font-semibold text-green-600">{country.GEM ? country.GEM.toFixed(1) : '-'}</td>
                                  <td className="px-4 py-3 font-semibold">{country.IES.toFixed(2)}</td>
                                  <td className="px-4 py-3 font-semibold">{country.EEF.toFixed(2)}</td>

                                  <td className="px-4 py-3 text-gray-600">{country.RTC}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.ICT}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.IAW}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.PIM}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.SCW}</td>

                                  <td className="px-4 py-3 text-gray-600">{country.FA}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.RFQ}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.MD}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.KI}</td>
                                  <td className="px-4 py-3 text-gray-600">{country.EN}</td>

                                  <td className="px-4 py-3 text-xs">
                                      <span className="px-2 py-1 rounded-full bg-gray-100 text-gray-700 whitespace-nowrap">
                                          {country.quadrant}
                                      </span>
                                  </td>
                                  <td className="px-4 py-3 text-xs text-gray-500 whitespace-nowrap">{country.typology}</td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
              {processedData.length === 0 && (
                  <div className="p-8 text-center text-gray-500">
                      Filtrelere uygun veri bulunamadı.
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

export default Comparison;

export interface CountryData {
  name: string;
  code: string;
  flag: string;
  // IES Components
  RTC: number;
  ICT: number;
  IAW: number;
  PIM: number;
  SCW: number;
  // EEF Components
  FA: number;
  RFQ: number;
  MD: number;
  KI: number;
  EN: number;
  // Calculated
  IES: number;
  EEF: number;
  SEGRI: number;
  quadrant: string;
  typology: string;
  GEM: number; // Normalized GEM NECI Score (0-100)
  B_READY: number; // World Bank Business Ready Score (0-100)
}

export type QuadrantType = "Iron Man" | "Captain America" | "Black Panther" | "Spider-Man";

export interface ComponentWeight {
  code: string;
  name: string;
  weight: number;
  description: string;
}

export interface SectorRiskWeights {
  TRF: number; // Technological Risk
  TZR: number; // Supply Chain Risk
  JRF: number; // Geopolitical Risk
  ESG: number; // ESG Risk
  ORF: number; // Operational Risk
}

export type SectorName = "Teknoloji" | "Üretim" | "Finans" | "Enerji" | "Perakende" | "Sağlık" | "Tarım" | "Lojistik";

