import React, { useState, useMemo } from 'react';
import { useCountries } from '../hooks';
import { LoadingState, ErrorState } from './Common';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid, ScatterChart, Scatter, ReferenceLine, Label } from 'recharts';
import { ArrowUpDown, Filter, ChevronUp, ChevronDown, CheckSquare, Square, X, Globe, TrendingUp, Building2, BarChart3, Layers } from 'lucide-react';
import { COLORS } from '../constants';

const Comparison: React.FC = () => {
  const { data, isLoading, isError, error } = useCountries();
  const [selectedCodes, setSelectedCodes] = useState<string[]>(['TR', 'US', 'SG']);

  // Table State
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'SEGRI', direction: 'desc' });
  const [filters, setFilters] = useState({ quadrant: 'All', typology: 'All' });

  // Comparison View State
  const [comparisonMetric, setComparisonMetric] = useState<'all' | 'gem' | 'b_ready'>('all');

  if (isLoading) return <LoadingState />;
  if (isError) return <ErrorState error={error} />;
  if (!data) return null;

  const handleToggle = (code: string) => {
    if (selectedCodes.includes(code)) {
        if(selectedCodes.length > 1) {
            setSelectedCodes(prev => prev.filter(c => c !== code));
        }
    } else {
      if (selectedCodes.length < 5) {
        setSelectedCodes(prev => [...prev, code]);
      } else {
          alert("Maksimum 5 ülke karşılaştırabilirsiniz.");
      }
    }
  };

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'desc';

    // Smart default: Text columns ASC, Numeric columns DESC
    const isTextColumn = ['name', 'quadrant', 'typology'].includes(key);

    if (sortConfig.key === key) {
        // Toggle if already sorted by this key
        direction = sortConfig.direction === 'asc' ? 'desc' : 'asc';
    } else {
        // Initial click on new column
        direction = isTextColumn ? 'asc' : 'desc';
    }

    setSortConfig({ key, direction });
  };

  const processedData = useMemo(() => {
      let temp = [...data];
      if (filters.quadrant !== 'All') temp = temp.filter(c => c.quadrant === filters.quadrant);
      if (filters.typology !== 'All') temp = temp.filter(c => c.typology === filters.typology);

      return temp.sort((a, b) => {
          const valA = (a as any)[sortConfig.key];
          const valB = (b as any)[sortConfig.key];

          // Robust handling for null/undefined
          if (valA === valB) return 0;
          if (valA === null || valA === undefined) return 1;
          if (valB === null || valB === undefined) return -1;

          if (typeof valA === 'string' && typeof valB === 'string') {
               return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          }

          // Assume numbers if not strings
          return sortConfig.direction === 'asc' ? (valA as number) - (valB as number) : (valB as number) - (valA as number);
      });
  }, [data, filters, sortConfig]);

  const selectedCountries = data.filter(c => selectedCodes.includes(c.code));

  // Prepare Radar Data
  const radarData = [
    { subject: 'Risk Alma (RTC)', fullMark: 100 },
    { subject: 'İnovasyon (ICT)', fullMark: 100 },
    { subject: 'Özerklik (IAW)', fullMark: 100 },
    { subject: 'Tutku (PIM)', fullMark: 100 },
    { subject: 'Sosyal (SCW)', fullMark: 100 },
    { subject: 'Finans (FA)', fullMark: 100 },
    { subject: 'Regülasyon (RFQ)', fullMark: 100 },
    { subject: 'Pazar (MD)', fullMark: 100 },
    { subject: 'Bilgi (KI)', fullMark: 100 },
    { subject: 'Ağlar (EN)', fullMark: 100 },
  ];

  const radarChartData = radarData.map(item => {
      const obj: any = { subject: item.subject, fullMark: 100 };
      selectedCountries.forEach(c => {
          let val = 0;
          const codeMap: Record<string, string> = {
              'Risk Alma (RTC)': 'RTC', 'İnovasyon (ICT)': 'ICT', 'Özerklik (IAW)': 'IAW', 'Tutku (PIM)': 'PIM', 'Sosyal (SCW)': 'SCW',
              'Finans (FA)': 'FA', 'Regülasyon (RFQ)': 'RFQ', 'Pazar (MD)': 'MD', 'Bilgi (KI)': 'KI', 'Ağlar (EN)': 'EN'
          };
          val = (c as any)[codeMap[item.subject]];
          obj[c.name] = val;
      });
      return obj;
  });

  const colors = ['#8884d8', '#82ca9d', '#ffc658', '#ff7300', '#00C49F'];

  const quadrants = Array.from(new Set(data.map(c => c.quadrant)));
  const typologies = Array.from(new Set(data.map(c => c.typology)));

  const SortHeader = ({ label, k }: { label: string, k: string }) => (
      <th className="px-4 py-3 border-b text-left text-xs font-bold text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-50 transition-colors" onClick={() => handleSort(k)}>
          <div className="flex items-center gap-1">
              {label}
              {sortConfig.key === k ? (
                  sortConfig.direction === 'asc' ? <ChevronUp size={14} className="text-blue-600"/> : <ChevronDown size={14} className="text-blue-600"/>
              ) : <ArrowUpDown size={14} className="opacity-30"/>}
          </div>
      </th>
  );

  const CustomIndexTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-4 border border-gray-100 shadow-xl rounded-lg text-sm">
          <p className="font-bold text-gray-800 mb-2 border-b pb-1">{label}</p>
          {payload.map((entry: any, index: number) => {
             const isSegri = entry.name.includes('SEGRİ');
             return (
               <div key={index} className="flex justify-between items-center gap-4 mb-1">
                  <span className="flex items-center gap-2" style={{ color: entry.fill }}>
                     <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.fill }}></span>
                     {entry.name}:
                  </span>
                  <span className="font-bold">{Number(entry.value).toFixed(2)}</span>
               </div>
             )
          })}
          {payload.length > 1 && (
             <div className="mt-2 pt-2 border-t border-dashed border-gray-200 text-xs text-gray-500">
                {payload.find((p:any) => p.name.includes('GEM')) && (
                    <div className="flex justify-between">
                        <span>Fark (SEGRİ - GEM):</span>
                        <span className={`font-bold ${(payload.find((p:any) => p.name.includes('SEGRİ')).value - payload.find((p:any) => p.name.includes('GEM')).value) > 0 ? 'text-green-600' : 'text-red-500'}`}>
                           {(payload.find((p:any) => p.name.includes('SEGRİ')).value - payload.find((p:any) => p.name.includes('GEM')).value).toFixed(1)}
                        </span>
                    </div>
                )}
                {payload.find((p:any) => p.name.includes('B-READY')) && (
                    <div className="flex justify-between">
                        <span>Fark (SEGRİ - B-READY):</span>
                        <span className={`font-bold ${(payload.find((p:any) => p.name.includes('SEGRİ')).value - payload.find((p:any) => p.name.includes('B-READY')).value) > 0 ? 'text-green-600' : 'text-red-500'}`}>
                           {(payload.find((p:any) => p.name.includes('SEGRİ')).value - payload.find((p:any) => p.name.includes('B-READY')).value).toFixed(1)}
                        </span>
                    </div>
                )}
             </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-8">
      {/* Active Selection Display */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <h3 className="font-bold mb-4 text-gray-800 flex items-center gap-2">
            Karşılaştırılan Ülkeler <span className="text-xs font-normal text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full">{selectedCountries.length}/5</span>
        </h3>
        <div className="flex flex-wrap gap-2">
            {selectedCountries.map(country => (
                <div key={country.code} className="flex items-center gap-2 bg-blue-50 border border-blue-200 text-blue-800 px-3 py-1.5 rounded-lg shadow-sm">
                    <span className="text-lg">{country.flag}</span>
                    <span className="font-medium text-sm">{country.name}</span>
                    <button onClick={() => handleToggle(country.code)} className="hover:text-red-500 transition-colors">
                        <X size={16} />
                    </button>
                </div>
            ))}
            {selectedCountries.length < 5 && (
                <div className="px-3 py-1.5 rounded-lg border border-dashed border-gray-300 text-gray-400 text-sm flex items-center">
                    + Tablodan ülke seçin
                </div>
            )}
        </div>
      </div>

      {/* Visual Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-[500px]">
            <h3 className="font-bold mb-4 text-center text-gray-800">Bileşen Analizi (Radar)</h3>
            <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarChartData}>
                <PolarGrid />
                <PolarAngleAxis dataKey="subject" tick={{ fontSize: 10 }} />
                <PolarRadiusAxis angle={30} domain={[0, 100]} />
                {selectedCountries.map((country, index) => (
                    <Radar
                        key={country.code}
                        name={country.name}
                        dataKey={country.name}
                        stroke={colors[index % colors.length]}
                        fill={colors[index % colors.length]}
                        fillOpacity={0.1}
                    />
                ))}
                <Legend />
                <Tooltip />
                </RadarChart>
            </ResponsiveContainer>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-[500px]">
             <h3 className="font-bold mb-4 text-center text-gray-800">SEGRİ Ana Puan Karşılaştırması</h3>
             <ResponsiveContainer width="100%" height="100%">
                 <BarChart data={selectedCountries} layout="vertical" margin={{ left: 40, right: 40 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" domain={[0, 100]} />
                    <YAxis dataKey="name" type="category" width={80} tick={{fontSize: 12, fontWeight: 500}} />
                    <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'}} />
                    <Legend />
                    <Bar dataKey="IES" fill="#8884d8" name="Bireysel (IES)" radius={[0, 4, 4, 0]} barSize={20} />
                    <Bar dataKey="EEF" fill="#82ca9d" name="Ekosistem (EEF)" radius={[0, 4, 4, 0]} barSize={20} />
                    <Bar dataKey="SEGRI" fill="#ff7300" name="SEGRİ" radius={[0, 4, 4, 0]} barSize={20} />
                 </BarChart>
             </ResponsiveContainer>
          </div>
      </div>

      {/* External Indices Comparison Section */}
      <div className="bg-gradient-to-r from-gray-50 to-white p-6 rounded-xl shadow-sm border border-gray-200">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 mb-6">
            <div className="flex items-center gap-3">
                <div className="bg-indigo-100 p-2 rounded-lg text-indigo-700">
                    <Globe size={24} />
