import { COUNTRY_DATA, SECTOR_WEIGHTS } from './constants';
import { CountryData, SectorName, SectorRiskWeights } from './types';
import { calculateIES, calculateEEF, calculateSEGRI, determineQuadrant, determineTypology } from './utils';

const SIMULATED_DELAY = 300; 

// Stateful data storage for Random Walk simulation
// We initialize with a deep copy to avoid mutating the constants, enabling the data to "evolve"
let liveCountries: CountryData[] = JSON.parse(JSON.stringify(COUNTRY_DATA));
let liveSectorWeights: Record<SectorName, SectorRiskWeights> = JSON.parse(JSON.stringify(SECTOR_WEIGHTS));

// Helper to fluctuate a score slightly (between -1.0 and +1.0)
// This simulates live market/sentiment changes relative to the PREVIOUS state (Random Walk)
const fluctuate = (value: number, volatility: number = 1.0) => {
  const change = (Math.random() * (volatility * 2)) - volatility;
  // Ensure we don't drift too far or go out of bounds (0-100)
  return Number(Math.min(100, Math.max(0, value + change)).toFixed(2));
};

export const fetchCountries = async (): Promise<CountryData[]> => {
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

  // Evolve the live dataset
  liveCountries = liveCountries.map(country => {
    // 1. Fluctuate Input Components based on their CURRENT (live) state
    const RTC = fluctuate(country.RTC);
    const ICT = fluctuate(country.ICT);
    const IAW = fluctuate(country.IAW);
    const PIM = fluctuate(country.PIM);
    const SCW = fluctuate(country.SCW);

    const FA = fluctuate(country.FA);
    const RFQ = fluctuate(country.RFQ);
    const MD = fluctuate(country.MD);
    const KI = fluctuate(country.KI);
    const EN = fluctuate(country.EN);

    // 2. Recalculate Derived Scores (Critical for Consistency)
    const IES = calculateIES(RTC, ICT, IAW, PIM, SCW);
    const EEF = calculateEEF(FA, RFQ, MD, KI, EN);
    const SEGRI = calculateSEGRI(IES, EEF);

    // 3. Re-evaluate Quadrant & Typology based on new scores
    const quadrant = determineQuadrant(IES, EEF);
    const typology = determineTypology(RTC, ICT, IAW, PIM, SCW);

    // 4. Fluctuate External Indices (Less volatile)
    const GEM = country.GEM ? fluctuate(country.GEM, 0.3) : country.GEM;
    const B_READY = country.B_READY ? fluctuate(country.B_READY, 0.3) : country.B_READY;

    // 5. Fluctuate Ecosystem Metrics
    // Unicorns are very stable, minimal to no fluctuation on this timescale
    // Startups fluctuate more often (new foundings / failures)
    const activeStartups = Math.max(0, Math.round(country.startupCount + ((Math.random() * 10) - 5)));

    return {
      ...country,
      RTC, ICT, IAW, PIM, SCW,
      FA, RFQ, MD, KI, EN,
      IES, EEF, SEGRI,
      quadrant, typology,
      GEM, B_READY,
      startupCount: activeStartups
    } as CountryData;
  });

  // Return a new array reference to trigger React re-renders
  return [...liveCountries];
};

export const fetchSectorWeights = async (): Promise<Record<SectorName, SectorRiskWeights>> => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

  const newWeights: Record<SectorName, SectorRiskWeights> = {} as any;

  // Evolve sector weights
  Object.keys(liveSectorWeights).forEach((key) => {
      const k = key as SectorName;
      const w = liveSectorWeights[k];

      // Weights are small decimals (e.g. 0.35), so we multiply by 100 to fluctuate, then divide back
      const evolved = {
          TRF: Number((fluctuate(w.TRF * 100, 1.5) / 100).toFixed(2)),
          TZR: Number((fluctuate(w.TZR * 100, 1.5) / 100).toFixed(2)),
          JRF: Number((fluctuate(w.JRF * 100, 1.5) / 100).toFixed(2)),
          ESG: Number((fluctuate(w.ESG * 100, 1.5) / 100).toFixed(2)),
          ORF: Number((fluctuate(w.ORF * 100, 1.5) / 100).toFixed(2)),
      };

      liveSectorWeights[k] = evolved;
      newWeights[k] = evolved;
  });

  return newWeights;
};

