import { useQuery, UseQueryOptions } from '@tanstack/react-query';
import { fetchCountries, fetchSectorWeights } from './api';
import { CountryData } from './types';
import { COUNTRY_DATA, SECTOR_WEIGHTS } from './constants';

export const QUERY_KEYS = {
  countries: ['countries'] as const,
  sectorWeights: ['sectorWeights'] as const,
};

export const useCountries = <T = CountryData[]>(
  options?: Omit<UseQueryOptions<CountryData[], Error, T>, 'queryKey' | 'queryFn'>
) => {
  return useQuery({
    queryKey: QUERY_KEYS.countries,
    queryFn: fetchCountries,
    // Use constants as initial data for instant first render
    initialData: COUNTRY_DATA,
    // Refresh data every 5 seconds to simulate real-time updates
    refetchInterval: 5000,
    // Keep staleTime low so updates are accepted
    staleTime: 1000,
    // Disable window focus refetching since we have active polling
    refetchOnWindowFocus: false,
    ...options,
  });
};

export const useSectorWeights = () => {
  return useQuery({
    queryKey: QUERY_KEYS.sectorWeights,
    queryFn: fetchSectorWeights,
    initialData: SECTOR_WEIGHTS,
    // Refresh sector risks every 10 seconds
    refetchInterval: 10000,
    staleTime: 1000,
    // Disable window focus refetching since we have active polling
    refetchOnWindowFocus: false,
  });
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSectorWeights, useCountries } from '../hooks';
import { LoadingState, ErrorState } from './Common';
import { SectorName } from '../types';
import { calculateRiskScore } from '../utils';
import { TrendingUp, AlertTriangle, ShieldCheck, Zap, Info } from 'lucide-react';

const RiskAnalysis: React.FC = () => {
  const { data: countries, isLoading: isCountriesLoading, isError: isCountriesError, error: countriesError } = useCountries();
  const { data: sectorWeights, isLoading: isWeightsLoading, isError: isWeightsError, error: weightsError } = useSectorWeights();

  const [selectedCountryCode, setSelectedCountryCode] = useState<string>('');
  const [selectedSector, setSelectedSector] = useState<SectorName>("Teknoloji");

  // Risk Inputs
  const [srfInputs, setSrfInputs] = useState({
    TRF: 50, TZR: 50, JRF: 50, ESG: 50, ORF: 50
  });

  // Blind Spot Inputs
  const [knaInputs, setKnaInputs] = useState({
    OKN: 50, SKN: 50, TKN: 50, KKN: 50
  });

  // Initial selection effect
  useEffect(() => {
    if (countries && countries.length > 0 && !selectedCountryCode) {
      setSelectedCountryCode(countries[0].code);
    }
  }, [countries, selectedCountryCode]);

  const activeCountry = countries?.find(c => c.code === selectedCountryCode);
  const activeWeights = sectorWeights ? sectorWeights[selectedSector] : null;

  // KNA Weights are fixed in prompt (30, 25, 25, 20)
  const knaWeights = { OKN: 0.30, SKN: 0.25, TKN: 0.25, KKN: 0.20 };

  const handleSrfChange = (key: string, val: string) => setSrfInputs(p => ({...p, [key]: parseInt(val)}));
  const handleKnaChange = (key: string, val: string) => setKnaInputs(p => ({...p, [key]: parseInt(val)}));

  const getRiskQuadrantInfo = (segri: number, riskMgmt: number) => {
      // Y-Axis: SEGRİ (Threshold 60)
      // X-Axis: Risk Mgmt (Threshold 65)

      if(segri >= 60 && riskMgmt >= 65) return { 
          id: 'leader',
          name: "LİDER DAYANIKLI", 
          icon: <TrendingUp size={24} />,
          bgGradient: "bg-gradient-to-br from-green-900 to-green-700",
          textColor: "text-green-100",
          accentColor: "text-green-400",
          borderColor: "border-green-500",
          desc: "Sürdürülebilir büyüme",
          strategy: "Mevcut risk yönetimini koruyarak pazar liderliğini sürdür."
      };
      if(segri >= 60 && riskMgmt < 65) return { 
          id: 'opportunist',
          name: "FIRSATÇI BÜYÜMECİ", 
          icon: <Zap size={24} />,
          bgGradient: "bg-gradient-to-br from-blue-900 to-blue-700",
          textColor: "text-blue-100",
          accentColor: "text-blue-400",
          borderColor: "border-blue-500",
          desc: "Risk yönetimi altyapısı kur",
          strategy: "Büyüme hızını korurken kurumsal risk yapılarını acilen oluştur."
      };
      if(segri < 60 && riskMgmt >= 65) return { 
          id: 'protector',
          name: "KORUYUCU DAYANIKLI", 
          icon: <ShieldCheck size={24} />,
          bgGradient: "bg-gradient-to-br from-purple-900 to-purple-700",
          textColor: "text-purple-100",
          accentColor: "text-purple-400",
          borderColor: "border-purple-500",
          desc: "Girişimcilik kapasitesini artır",
          strategy: "Güçlü yapıyı koruyarak inovasyon ve girişimcilik kaslarını geliştir."
      };
      return { 
          id: 'risky',
          name: "RİSKLİ KIRILGAN", 
          icon: <AlertTriangle size={24} />,
          bgGradient: "bg-gradient-to-br from-red-900 to-red-700",
          textColor: "text-red-100",
          accentColor: "text-red-400",
          borderColor: "border-red-500",
          desc: "Acil transformasyon",
          strategy: "Kriz yönetimi ilan et ve köklü yapısal dönüşüm başlat."
      };
  };

  if (isCountriesLoading || isWeightsLoading) return <LoadingState />;
  if (isCountriesError) return <ErrorState error={countriesError} />;
  if (isWeightsError) return <ErrorState error={weightsError} />;
  if (!countries || !sectorWeights || !activeCountry || !activeWeights) return null;

  // Calculate scores directly during render (Derived State)
  const srfScore = calculateRiskScore(srfInputs, activeWeights);
  const knaScore = calculateRiskScore(knaInputs, knaWeights);
  const srkaResult = (0.40 * activeCountry.SEGRI) + (0.35 * srfScore) + (0.25 * knaScore);

  const riskMgmtScore = ((0.35 * srfScore) + (0.25 * knaScore)) / 0.60;
  const quadrantInfo = getRiskQuadrantInfo(activeCountry.SEGRI, riskMgmtScore);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-12">
        <div className="lg:col-span-8 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-medium mb-1">Ülke Seçimi</label>
                        <select 
                            className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none"
                            value={selectedCountryCode}
                            onChange={(e) => setSelectedCountryCode(e.target.value)}
                        >
                            {countries.map(c => <option key={c.code} value={c.code}>{c.flag} {c.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">Sektör Seçimi</label>
                        <select 
                            className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none"
                            value={selectedSector}
                            onChange={(e) => setSelectedSector(e.target.value as SectorName)}
                        >
                            {Object.keys(sectorWeights).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* SRF Inputs */}
                    <div>
                        <h4 className="font-bold text-gray-700 mb-3 border-b pb-2 flex justify-between">
                            <span>SRF: Sektörel Risk Yönetimi</span>
                            <span className="text-sm bg-gray-100 px-2 py-0.5 rounded text-gray-600">%35</span>
                        </h4>
                        <p className="text-xs text-gray-500 mb-4">Puan ne kadar yüksekse, risk yönetimi o kadar güçlüdür.</p>
                        {Object.entries(srfInputs).map(([key, val]) => (
                            <div key={key} className="mb-3">
                                <div className="flex justify-between text-sm mb-1">
                                    <span>{key} (Ağırlık: %{(activeWeights as any)[key] * 100})</span>
                                    <span className="font-bold">{val}</span>
                                </div>
                                <input type="range" min="0" max="100" value={val} onChange={(e) => handleSrfChange(key, e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600" />
                            </div>
                        ))}
                    </div>

                    {/* KNA Inputs */}
                    <div>
                         <h4 className="font-bold text-gray-700 mb-3 border-b pb-2 flex justify-between">
                            <span>KNA: Kör Nokta Farkındalığı</span>
                            <span className="text-sm bg-gray-100 px-2 py-0.5 rounded text-gray-600">%25</span>
                        </h4>
                        <p className="text-xs text-gray-500 mb-4">Puan ne kadar yüksekse, kör noktalar o kadar azdır (farkındalık yüksek).</p>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>OKN: Organizasyonel (%30)</span><span className="font-bold">{knaInputs.OKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.OKN} onChange={(e) => handleKnaChange('OKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-green-600" />
                        </div>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>SKN: Sektörel (%25)</span><span className="font-bold">{knaInputs.SKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.SKN} onChange={(e) => handleKnaChange('SKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-green-600" />
                        </div>
                        <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>TKN: Teknolojik (%25)</span><span className="font-bold">{knaInputs.TKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.TKN} onChange={(e) => handleKnaChange('TKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-green-600" />
                        </div>
                         <div className="mb-3">
                            <div className="flex justify-between text-sm mb-1"><span>KKN: Kültürel (%20)</span><span className="font-bold">{knaInputs.KKN}</span></div>
                            <input type="range" min="0" max="100" value={knaInputs.KKN} onChange={(e) => handleKnaChange('KKN', e.target.value)} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-green-600" />
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="lg:col-span-4 space-y-6">
            {/* Main Score Card with Dynamic Theme */}
            <div className={`${quadrantInfo.bgGradient} text-white p-6 rounded-xl shadow-lg flex flex-col justify-center items-center text-center relative overflow-hidden transition-all duration-500 ring-1 ring-white/10`}>
