const ResourceCard = ({ title, url, desc, items, mapping, color }: any) => {
    let themeClass = 'border-gray-100 hover:border-gray-300';
    let titleClass = 'text-gray-700';
    let bgClass = 'bg-gray-50';

    if (color === 'blue') {
        themeClass = 'border-blue-100 hover:border-blue-300';
        titleClass = 'text-blue-700';
        bgClass = 'bg-blue-50';
    } else if (color === 'green') {
        themeClass = 'border-green-100 hover:border-green-300';
        titleClass = 'text-green-700';
        bgClass = 'bg-green-50';
    } else if (color === 'purple') {
        themeClass = 'border-purple-100 hover:border-purple-300';
        titleClass = 'text-purple-700';
        bgClass = 'bg-purple-50';
    }

    return (
        <div className={`border rounded-lg p-5 hover:shadow-md transition-all duration-200 bg-white ${themeClass}`}>
            <div className="flex justify-between items-start mb-3">
                <h4 className={`font-bold text-lg ${titleClass}`}>{title}</h4>
                <a href={url} target="_blank" rel="noopener noreferrer" className="text-xs bg-gray-100 hover:bg-gray-200 px-3 py-1.5 rounded-full flex items-center gap-1.5 text-gray-600 transition-colors">
                    Web <ExternalLink size={12} />
                </a>
            </div>
            <p className="text-sm text-gray-600 mb-4 leading-relaxed">{desc}</p>

            <div className="grid grid-cols-1 gap-4 text-sm">
                <div className="flex flex-wrap gap-x-6 gap-y-1 text-xs text-gray-500">
                    {items.map((item: any, i: number) => (
                        <div key={i}>
                            <span className="font-semibold text-gray-700">{item.label}:</span> {item.value}
                        </div>
                    ))}
                </div>
                <div className={`${bgClass} p-3 rounded-lg border border-opacity-50 border-gray-200`}>
                    <p className="font-bold text-[10px] text-gray-500 mb-2 uppercase tracking-wider">SEGRİ Bileşen Eşleştirmesi</p>
                    <div className="space-y-1.5">
                        {mapping.map((m: any, i: number) => (
                            <div key={i} className="flex items-center text-xs">
                                <span className={`font-bold w-12 shrink-0 ${titleClass}`}>{m.code}</span>
                                <span className="text-gray-600 truncate">{m.text}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

