import React, { useState, useEffect, useMemo } from 'react';
import { useCountries } from '../hooks';
import { LoadingState, ErrorState } from './Common';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, Legend } from 'recharts';
import { MapPin, Trophy, TrendingUp, Activity, Users, Globe, Building2, AlertCircle, ChevronDown, Flag, Brain, Sword, Heart, Target, Hammer, Shield, Zap, Rocket, Gem, LayoutGrid, ArrowUpRight, ArrowRight, CheckCircle2, Info } from 'lucide-react';
import { COLORS } from '../constants';

const CountryDetail: React.FC = () => {
  const { data, isLoading, isError, error } = useCountries();
  const [selectedCode, setSelectedCode] = useState<string>('');

  useEffect(() => {
    if (data && data.length > 0 && !selectedCode) {
      setSelectedCode(data[0].code);
    }
  }, [data, selectedCode]);

  // Memoize heavy calculations
  const stats = useMemo(() => {
    if (!data || !selectedCode) return null;

    const country = data.find(c => c.code === selectedCode);
    if (!country) return null;

    const sortedData = [...data].sort((a, b) => b.SEGRI - a.SEGRI);
    const rank = sortedData.findIndex(c => c.code === selectedCode) + 1;
    const totalCountries = data.length;

    const averages = {
      IES: data.reduce((acc, c) => acc + c.IES, 0) / totalCountries,
      EEF: data.reduce((acc, c) => acc + c.EEF, 0) / totalCountries,
      SEGRI: data.reduce((acc, c) => acc + c.SEGRI, 0) / totalCountries
    };

    return { country, rank, totalCountries, averages };
  }, [data, selectedCode]);

  const maturity = useMemo(() => {
      if (!stats) return null;
      const count = stats.country.unicornCount;
      if (count >= 50) return { label: 'Global Lider', color: 'text-purple-700 bg-purple-50 border-purple-200', desc: 'Dünya çapında inovasyon merkezi' };
      if (count >= 20) return { label: 'Olgun Ekosistem', color: 'text-green-700 bg-green-50 border-green-200', desc: 'Sürdürülebilir unicorn üretimi' };
      if (count >= 5) return { label: 'Yükselen', color: 'text-blue-700 bg-blue-50 border-blue-200', desc: 'Hızla büyüyen girişim havuzu' };
      if (count >= 1) return { label: 'Gelişen', color: 'text-orange-700 bg-orange-50 border-orange-200', desc: 'İlk başarı hikayeleri' };
      return { label: 'Başlangıç', color: 'text-gray-700 bg-gray-50 border-gray-200', desc: 'Henüz unicorn çıkarmamış' };
  }, [stats]);

  if (isLoading) return <LoadingState />;
  if (isError) return <ErrorState error={error} />;
  if (!data || !stats) return null;

  const { country, rank, totalCountries, averages } = stats;

  const getTypologyIcon = (type: string) => {
    switch(type) {
      case 'Gandalf Tipi': return <Brain className="w-5 h-5" />;
      case 'Aragorn Tipi': return <Sword className="w-5 h-5" />;
      case 'Frodo Tipi': return <Heart className="w-5 h-5" />;
      case 'Legolas Tipi': return <Target className="w-5 h-5" />;
      case 'Gimli Tipi': return <Hammer className="w-5 h-5" />;
      case 'Galadriel Tipi': return <Shield className="w-5 h-5" />;
      case 'Han Solo Tipi': return <Zap className="w-5 h-5" />;
      default: return <Users className="w-5 h-5" />;
    }
  };

  // Prepare Radar Data
  const radarData = [
    { subject: 'Risk (RTC)', A: country.RTC, fullMark: 100 },
    { subject: 'İnovasyon (ICT)', A: country.ICT, fullMark: 100 },
    { subject: 'Özerklik (IAW)', A: country.IAW, fullMark: 100 },
    { subject: 'Motivasyon (PIM)', A: country.PIM, fullMark: 100 },
    { subject: 'Sosyal (SCW)', A: country.SCW, fullMark: 100 },
    { subject: 'Finans (FA)', A: country.FA, fullMark: 100 },
    { subject: 'Regülasyon (RFQ)', A: country.RFQ, fullMark: 100 },
    { subject: 'Pazar (MD)', A: country.MD, fullMark: 100 },
    { subject: 'Bilgi (KI)', A: country.KI, fullMark: 100 },
    { subject: 'Ağlar (EN)', A: country.EN, fullMark: 100 },
  ];

  // Comparison Data
  const comparisonData = [
    { name: 'Bireysel (IES)', Ülke: country.IES, Ortalama: averages.IES },
    { name: 'Ekosistem (EEF)', Ülke: country.EEF, Ortalama: averages.EEF },
    { name: 'Genel (SEGRİ)', Ülke: country.SEGRI, Ortalama: averages.SEGRI },
  ];

  const getQuadColor = (q: string) => {
    if(q === "Iron Man") return "text-green-300 border-green-400/30 bg-green-500/20";
    if(q === "Captain America") return "text-orange-300 border-orange-400/30 bg-orange-500/20";
    if(q === "Black Panther") return "text-purple-300 border-purple-400/30 bg-purple-500/20";
    return "text-blue-300 border-blue-400/30 bg-blue-500/20";
  };

  // Quadrant Strategy Definitions
  const quadrantStrategies: Record<string, { title: string, subtitle: string, desc: string, strategy: string, colorClass: string }> = {
