import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Activity, Home } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
    errorInfo: null
  };

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error, errorInfo: null };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
    this.setState({ errorInfo });
  }

  public handleReload = () => {
    window.location.reload();
  };

  public handleHome = () => {
    this.setState({ hasError: false, error: null });
    window.location.href = '/';
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
          <div className="max-w-md w-full bg-white rounded-xl shadow-lg border border-red-100 overflow-hidden animate-in fade-in zoom-in duration-300">
            {/* Header */}
            <div className="bg-red-50 p-6 flex flex-col items-center border-b border-red-100">
              <div className="p-3 bg-red-100 text-red-600 rounded-full mb-4 shadow-sm">
                <AlertTriangle size={48} />
              </div>
              <h2 className="text-2xl font-bold text-gray-900 text-center">Beklenmeyen Bir Hata Oluştu</h2>
              <p className="text-red-600 text-sm mt-2 text-center">
                Sistem bir sorunla karşılaştı ve işlemi tamamlayamadı.
              </p>
            </div>

            {/* Content */}
            <div className="p-6">
              <div className="bg-gray-50 rounded-lg p-4 mb-6 border border-gray-200">
                <div className="flex items-center gap-2 mb-2 text-gray-700 font-semibold text-sm">
                   <Activity size={16} /> Teknik Detay
                </div>
                <code className="text-xs text-gray-500 font-mono break-words block bg-white p-2 rounded border border-gray-100">
                  {this.state.error?.message || 'Bilinmeyen Hata'}
                </code>
              </div>

              <div className="flex flex-col gap-3">
                <button
                  onClick={this.handleReload}
                  className="w-full py-3 px-4 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center gap-2 shadow-sm"
                >
                  <RefreshCw size={18} />
                  Sayfayı Yenile
                </button>

                <button
                  onClick={this.handleHome}
                  className="w-full py-3 px-4 bg-white hover:bg-gray-50 text-gray-700 border border-gray-200 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                >
                  <Home size={18} />
                  Ana Sayfaya Dön
                </button>
              </div>
            </div>

            {/* Footer */}
            <div className="bg-gray-50 px-6 py-4 border-t border-gray-100 text-center">
              <p className="text-xs text-gray-400">
                Sorun devam ederse lütfen sistem yöneticisi ile iletişime geçin.
                <br/>
                Hata Kodu: SEGRİ-RUNTIME-ERR
              </p>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import App from './App';
import { ErrorBoundary } from './components/ErrorBoundary';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // 5 minutes
      gcTime: 1000 * 60 * 10, // 10 minutes
      refetchOnWindowFocus: true, // Enabled for background updates
      retry: 1,
      // Do not throw errors to the boundary for queries, handle them via isError in components
      throwOnError: false, 
    },
    mutations: {
       // Log mutation errors globally
       onError: (error) => {
           console.error("Global Mutation Error:", error);
       }
    }
  },
});

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <ErrorBoundary>
        <App />
      </ErrorBoundary>
    </QueryClientProvider>
  </React.StrictMode>
);

