          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import { COUNTRY_DATA, SECTOR_WEIGHTS } from './constants';
import { CountryData, SectorName, SectorRiskWeights } from './types';
import { calculateIES, calculateEEF, calculateSEGRI, determineQuadrant, determineTypology } from './utils';

const SIMULATED_DELAY = 400; 

// Stateful data storage for Random Walk simulation
// We initialize with a deep copy to avoid mutating the constants
let liveCountries: CountryData[] = JSON.parse(JSON.stringify(COUNTRY_DATA));
let liveSectorWeights: Record<SectorName, SectorRiskWeights> = JSON.parse(JSON.stringify(SECTOR_WEIGHTS));

// Helper to fluctuate a score slightly (between -range and +range)
// Volatility determines how drastic the change is
const fluctuate = (value: number, volatility: number = 0.8) => {
  const change = (Math.random() * (volatility * 2)) - volatility;
  // Ensure we don't drift too far or go out of bounds (0-100)
  return Number(Math.min(100, Math.max(0, value + change)).toFixed(2));
};

export const fetchCountries = async (): Promise<CountryData[]> => {
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

  // Optimization: Only update ~20% of the countries per tick
  // This maintains referential equality for 80% of the data, allowing React.memo and useMemo to be effective
  const updateCount = Math.max(1, Math.floor(liveCountries.length * 0.2));
  const indicesToUpdate = new Set<number>();

  while (indicesToUpdate.size < updateCount) {
    indicesToUpdate.add(Math.floor(Math.random() * liveCountries.length));
  }

  // Evolve the live dataset
  liveCountries = liveCountries.map((country, index) => {
    // If this country wasn't selected for an update, return the EXACT same object reference
    if (!indicesToUpdate.has(index)) {
        return country;
    }

    // 1. Fluctuate Input Components based on their CURRENT (live) state
    const RTC = fluctuate(country.RTC);
    const ICT = fluctuate(country.ICT);
    const IAW = fluctuate(country.IAW);
    const PIM = fluctuate(country.PIM);
    const SCW = fluctuate(country.SCW);

    const FA = fluctuate(country.FA);
    const RFQ = fluctuate(country.RFQ);
    const MD = fluctuate(country.MD);
    const KI = fluctuate(country.KI);
    const EN = fluctuate(country.EN);

    // 2. Recalculate Derived Scores (Critical for Consistency)
    const IES = calculateIES(RTC, ICT, IAW, PIM, SCW);
    const EEF = calculateEEF(FA, RFQ, MD, KI, EN);
    const SEGRI = calculateSEGRI(IES, EEF);

    // 3. Re-evaluate Quadrant & Typology based on new scores
    const quadrant = determineQuadrant(IES, EEF);
    const typology = determineTypology(RTC, ICT, IAW, PIM, SCW);

    // 4. Fluctuate External Indices (Less volatile, lower probability of change)
    const GEM = Math.random() > 0.8 ? (country.GEM ? fluctuate(country.GEM, 0.2) : country.GEM) : country.GEM;
    const B_READY = Math.random() > 0.8 ? (country.B_READY ? fluctuate(country.B_READY, 0.2) : country.B_READY) : country.B_READY;

    // 5. Fluctuate Ecosystem Metrics (Startups fluctuate, Unicorns mostly stable but can change on fetch)
    // Only change startups occasionally
    let startupCount = country.startupCount;
    if (Math.random() > 0.7) {
        startupCount = Math.max(0, Math.round(country.startupCount + ((Math.random() * 10) - 5)));
    }

    // Simulate Unicorn Data Fetch Updates (Very stable, but changes rarely or on specific events)
    // We add a small chance to fluctuate this so the "Fetch" button feels alive
    let unicornCount = country.unicornCount;
    if (Math.random() > 0.9) {
        // Small fluctuation 0, +1 or -1
        const change = Math.floor(Math.random() * 3) - 1; 
        unicornCount = Math.max(0, country.unicornCount + change);
    }

    // Return a NEW object reference for the updated country
    return {
      ...country,
      RTC, ICT, IAW, PIM, SCW,
      FA, RFQ, MD, KI, EN,
      IES, EEF, SEGRI,
      quadrant, typology,
      GEM, B_READY,
      startupCount,
      unicornCount
    } as CountryData;
  });

  // Return a new array reference to trigger React Query data update
  return [...liveCountries];
};

export const fetchSectorWeights = async (): Promise<Record<SectorName, SectorRiskWeights>> => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

  // Create a new container object
  const newWeights: Record<SectorName, SectorRiskWeights> = { ...liveSectorWeights };

  // Pick one random sector to update instead of all
  const sectors = Object.keys(liveSectorWeights) as SectorName[];
  const sectorToUpdate = sectors[Math.floor(Math.random() * sectors.length)];

  const w = liveSectorWeights[sectorToUpdate];

  // Evolve weights
  const evolved = {
      TRF: Number((fluctuate(w.TRF * 100, 1.0) / 100).toFixed(2)),
      TZR: Number((fluctuate(w.TZR * 100, 1.0) / 100).toFixed(2)),
      JRF: Number((fluctuate(w.JRF * 100, 1.0) / 100).toFixed(2)),
      ESG: Number((fluctuate(w.ESG * 100, 1.0) / 100).toFixed(2)),
      ORF: Number((fluctuate(w.ORF * 100, 1.0) / 100).toFixed(2)),
  };

  // Update state and return object
  liveSectorWeights[sectorToUpdate] = evolved;
  newWeights[sectorToUpdate] = evolved;

  return newWeights;
};

import { useQuery, UseQueryOptions } from '@tanstack/react-query';
import { fetchCountries, fetchSectorWeights } from './api';
import { CountryData } from './types';
import { COUNTRY_DATA, SECTOR_WEIGHTS } from './constants';

export const QUERY_KEYS = {
  countries: ['countries'] as const,
  sectorWeights: ['sectorWeights'] as const,
};

// Generic hook to fetch all countries with optional selection logic
export const useCountries = <T = CountryData[]>(
  options?: Omit<UseQueryOptions<CountryData[], Error, T>, 'queryKey' | 'queryFn' | 'initialData'>
) => {
  return useQuery({
    queryKey: QUERY_KEYS.countries,
    queryFn: fetchCountries,
    // Use constants as initial data for instant first render (Hydration)
    initialData: COUNTRY_DATA,
    // Refresh data every 5 seconds to simulate real-time updates
    refetchInterval: 5000,
    // Keep staleTime low so updates are accepted, but high enough to prevent
    // rapid re-fetches if multiple components mount simultaneously
    staleTime: 2000,
    // Enable window focus refetching for better user experience when returning to tab
    refetchOnWindowFocus: true,
    // Ensure structural sharing is enabled to prevent re-renders if selected data hasn't changed
    structuralSharing: true,
    ...options,
  });
};

// Specialized hook to fetch a single country by code
// Uses the 'select' option to subscribe ONLY to the specific country's data changes.
// This prevents the component from re-rendering if OTHER countries update but this one doesn't.
export const useCountry = (code: string) => {
  return useCountries<CountryData | undefined>({
    select: (data) => data.find((c) => c.code === code),
    enabled: !!code,
  });
};

export const useSectorWeights = () => {
  return useQuery({
    queryKey: QUERY_KEYS.sectorWeights,
    queryFn: fetchSectorWeights,
    initialData: SECTOR_WEIGHTS,
    // Refresh sector risks every 10 seconds
    refetchInterval: 10000,
    staleTime: 5000,
    refetchOnWindowFocus: true,
  });
};

