import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Activity, Home } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
    errorInfo: null
  };

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error, errorInfo: null };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
    this.setState({ errorInfo });
  }

  public handleReload = () => {
    window.location.reload();
  };

  public handleHome = () => {
    this.setState({ hasError: false, error: null });
    window.location.href = '/';
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="w-full min-h-[400px] h-full flex items-center justify-center p-4">
          <div className="max-w-md w-full bg-white rounded-xl shadow-lg border border-red-100 overflow-hidden animate-in fade-in zoom-in duration-300 my-8">
            {/* Header */}
            <div className="bg-red-50 p-6 flex flex-col items-center border-b border-red-100">
              <div className="p-3 bg-red-100 text-red-600 rounded-full mb-4 shadow-sm">
                <AlertTriangle size={48} />
              </div>
              <h2 className="text-2xl font-bold text-gray-900 text-center">Beklenmeyen Bir Hata Oluştu</h2>
              <p className="text-red-600 text-sm mt-2 text-center">
                Sistem bir sorunla karşılaştı ve işlemi tamamlayamadı.
              </p>
            </div>

            {/* Content */}
            <div className="p-6">
              <div className="bg-gray-50 rounded-lg p-4 mb-6 border border-gray-200">
                <div className="flex items-center gap-2 mb-2 text-gray-700 font-semibold text-sm">
                   <Activity size={16} /> Teknik Detay
                </div>
                <code className="text-xs text-gray-500 font-mono break-words block bg-white p-2 rounded border border-gray-100 max-h-32 overflow-y-auto">
                  {this.state.error?.message || 'Bilinmeyen Hata'}
                </code>
              </div>

              <div className="flex flex-col gap-3">
                <button
                  onClick={this.handleReload}
                  className="w-full py-3 px-4 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center gap-2 shadow-sm"
                >
                  <RefreshCw size={18} />
                  Sayfayı Yenile
                </button>

                <button
                  onClick={this.handleHome}
                  className="w-full py-3 px-4 bg-white hover:bg-gray-50 text-gray-700 border border-gray-200 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                >
                  <Home size={18} />
                  Ana Sayfaya Dön
                </button>
              </div>
            </div>

            {/* Footer */}
            <div className="bg-gray-50 px-6 py-4 border-t border-gray-100 text-center">
              <p className="text-xs text-gray-400">
                Sorun devam ederse lütfen sistem yöneticisi ile iletişime geçin.
                <br/>
                Hata Kodu: SEGRİ-RUNTIME-ERR
              </p>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import React, { useState, useEffect } from 'react';
import { useCountries } from '../hooks';
import { calculateIES, calculateEEF, calculateSEGRI, determineQuadrant, determineTypology } from '../utils';
import { COLORS } from '../constants';
import { Download, Save, Trash2, BarChart2, RefreshCw, ChevronRight, Upload, Scale, Building2 } from 'lucide-react';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Legend, Tooltip } from 'recharts';

interface SavedProfile {
  id: number;
  name: string;
  date: string;
  inputs: typeof initialInputs;
  results: {
    IES: number;
    EEF: number;
    SEGRI: number;
    quadrant: string;
    typology: string;
  };
}

const initialInputs = {
  RTC: 50, ICT: 50, IAW: 50, PIM: 50, SCW: 50,
  FA: 50, RFQ: 50, MD: 50, KI: 50, EN: 50
};

const Calculator: React.FC = () => {
  const { data: countries } = useCountries();
  const [inputs, setInputs] = useState(initialInputs);

  const [results, setResults] = useState({
      IES: 0, EEF: 0, SEGRI: 0, quadrant: '', typology: ''
  });

  // New State for Features
  const [savedProfiles, setSavedProfiles] = useState<SavedProfile[]>([]);
  const [profileName, setProfileName] = useState('');
  const [compareCode, setCompareCode] = useState('');

  // Load saved profiles from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('segri_calculator_profiles');
    if (saved) {
      try {
        setSavedProfiles(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved profiles", e);
      }
    }
  }, []);

  // Calculate results whenever inputs change
  useEffect(() => {
    const ies = calculateIES(inputs.RTC, inputs.ICT, inputs.IAW, inputs.PIM, inputs.SCW);
    const eef = calculateEEF(inputs.FA, inputs.RFQ, inputs.MD, inputs.KI, inputs.EN);
    const segri = calculateSEGRI(ies, eef);
    const quad = determineQuadrant(ies, eef);
    const type = determineTypology(inputs.RTC, inputs.ICT, inputs.IAW, inputs.PIM, inputs.SCW);
    setResults({ IES: ies, EEF: eef, SEGRI: segri, quadrant: quad, typology: type });
  }, [inputs]);

  const handleChange = (key: string, val: string) => {
    setInputs(prev => ({ ...prev, [key]: Number(val) }));
  };

  const handleLoadCountry = (code: string) => {
    if (code === 'reset') {
        setInputs(initialInputs);
        setCompareCode('');
        return;
    }
    const country = countries?.find(c => c.code === code);
    if (country) {
        setInputs({
            RTC: country.RTC, ICT: country.ICT, IAW: country.IAW, PIM: country.PIM, SCW: country.SCW,
            FA: country.FA, RFQ: country.RFQ, MD: country.MD, KI: country.KI, EN: country.EN
        });
    }
  };

  // Save/Load Logic
  const handleSaveProfile = () => {
    if (!profileName.trim()) return;
    const newProfile: SavedProfile = {
      id: Date.now(),
      name: profileName,
      date: new Date().toLocaleDateString(),
      inputs: { ...inputs },
      results: { ...results }
    };
    const updated = [newProfile, ...savedProfiles];
    setSavedProfiles(updated);
    localStorage.setItem('segri_calculator_profiles', JSON.stringify(updated));
    setProfileName('');
  };

  const handleDeleteProfile = (id: number) => {
    const updated = savedProfiles.filter(p => p.id !== id);
    setSavedProfiles(updated);
    localStorage.setItem('segri_calculator_profiles', JSON.stringify(updated));
  };

  const handleLoadProfile = (profile: SavedProfile) => {
    setInputs(profile.inputs);
  };

  const getQuadColor = (q: string) => {
      if(q === "Iron Man") return COLORS.ironMan;
      if(q === "Captain America") return COLORS.captainAmerica;
      if(q === "Black Panther") return COLORS.blackPanther;
      return COLORS.spiderMan;
  };

  const comparisonCountry = countries?.find(c => c.code === compareCode);

  const radarData = [
    { subject: 'Risk (RTC)', Current: inputs.RTC, Target: comparisonCountry?.RTC || 0 },
    { subject: 'İnov (ICT)', Current: inputs.ICT, Target: comparisonCountry?.ICT || 0 },
    { subject: 'Özerk (IAW)', Current: inputs.IAW, Target: comparisonCountry?.IAW || 0 },
    { subject: 'Tutku (PIM)', Current: inputs.PIM, Target: comparisonCountry?.PIM || 0 },
    { subject: 'Sosyal (SCW)', Current: inputs.SCW, Target: comparisonCountry?.SCW || 0 },
    { subject: 'Finans (FA)', Current: inputs.FA, Target: comparisonCountry?.FA || 0 },
    { subject: 'Regül (RFQ)', Current: inputs.RFQ, Target: comparisonCountry?.RFQ || 0 },
    { subject: 'Pazar (MD)', Current: inputs.MD, Target: comparisonCountry?.MD || 0 },
    { subject: 'Bilgi (KI)', Current: inputs.KI, Target: comparisonCountry?.KI || 0 },
    { subject: 'Ağlar (EN)', Current: inputs.EN, Target: comparisonCountry?.EN || 0 },
  ];

  const DiffBadge = ({ current, target }: { current: number, target: number }) => {
      if (!comparisonCountry) return null;
      const diff = current - target;
      if (Math.abs(diff) < 0.1) return <span className="text-xs text-gray-400 ml-2">(=)</span>;
      const color = diff > 0 ? 'text-green-500' : 'text-red-500';
      const sign = diff > 0 ? '+' : '';
      return <span className={`text-xs font-bold ml-2 ${color}`}>({sign}{diff.toFixed(1)})</span>;
  };

  const Slider = ({ label, code, desc }: { label: string, code: string, desc: string }) => (
      <div className="mb-4">
          <div className="flex justify-between items-center mb-1">
              <label className="text-sm font-semibold text-gray-700">{label} ({code})</label>
              <div>
                  <span className="text-sm font-bold text-blue-600">{(inputs as any)[code]}</span>
                  {comparisonCountry && <DiffBadge current={(inputs as any)[code]} target={(comparisonCountry as any)[code]} />}
              </div>
          </div>
          <div className="relative">
              <input 
                type="range" min="0" max="100" 
                value={(inputs as any)[code]} 
                onChange={(e) => handleChange(code, e.target.value)}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600 relative z-10"
              />
              {comparisonCountry && (
                  <div 
                    className="absolute top-0 w-1 h-2 bg-gray-400 z-0 pointer-events-none" 
                    style={{ left: `${(comparisonCountry as any)[code]}%` }}
                    title={`${comparisonCountry.name}: ${(comparisonCountry as any)[code]}`}
                  ></div>
              )}
          </div>
          <p className="text-xs text-gray-400 mt-1 flex justify-between">
              <span>{desc}</span>
              {comparisonCountry && <span className="text-gray-500">{comparisonCountry.code}: {(comparisonCountry as any)[code]}</span>}
          </p>
      </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* Control Bar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 grid grid-cols-1 md:grid-cols-2 gap-4">

          {/* Load Template */}
          <div className="flex items-center gap-3">
              <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                  <Download size={20} />
              </div>
              <div className="flex-1">
                  <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Şablon Yükle</label>
                  <select 
                    className="w-full p-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                    onChange={(e) => handleLoadCountry(e.target.value)}
                    value=""
                  >
                      <option value="" disabled>Ülke Seçiniz...</option>
