                            <div className="font-bold text-gray-700 bg-gray-100 px-3 py-1 rounded-lg w-12 text-center text-sm tabular-nums">{item.v}</div>
                        </div>
                    </div>
                ))}
             </div>
          </div>
      </div>
    </div>
  );
};

