                       ))}
                       {filteredGlobalUnicorns.length === 0 && (
                           <tr>
                               <td colSpan={6} className="px-6 py-8 text-center text-gray-500">
                                   Arama kriterlerine uygun Unicorn bulunamadı.
                               </td>
                           </tr>
                       )}
                   </tbody>
               </table>
           </div>
      </div>
    </div>
  );
};

