import { COUNTRY_DATA, SECTOR_WEIGHTS, TOP_UNICORNS } from './constants';
import { CountryData, SectorName, SectorRiskWeights, Unicorn } from './types';
import { calculateIES, calculateEEF, calculateSEGRI, determineQuadrant, determineTypology } from './utils';

const SIMULATED_DELAY = 300; 

// Persistent state for simulation
let liveCountries: CountryData[] = JSON.parse(JSON.stringify(COUNTRY_DATA));
let liveSectorWeights: Record<SectorName, SectorRiskWeights> = JSON.parse(JSON.stringify(SECTOR_WEIGHTS));
let liveUnicorns: Unicorn[] = JSON.parse(JSON.stringify(TOP_UNICORNS));

/**
 * Generic fluctuation helper
 * @param value Current value
 * @param volatility Range of change
 * @param min Minimum possible value
 * @param max Maximum possible value
 */
const fluctuate = (value: number, volatility: number = 0.8, min: number = 0, max: number = 100) => {
  const change = (Math.random() * (volatility * 2)) - volatility;
  return Number(Math.max(min, Math.min(max, value + change)).toFixed(2));
};

export const fetchCountries = async (): Promise<CountryData[]> => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

  // Update about 60% of countries in each poll to simulate activity
  liveCountries = liveCountries.map((country) => {
    const shouldUpdate = Math.random() > 0.4;
    if (!shouldUpdate) return country;

    // 1. Fluctuate Core Components (IES & EEF)
    const RTC = fluctuate(country.RTC, 0.5);
    const ICT = fluctuate(country.ICT, 0.5);
    const IAW = fluctuate(country.IAW, 0.5);
    const PIM = fluctuate(country.PIM, 0.5);
    const SCW = fluctuate(country.SCW, 0.5);

    const FA = fluctuate(country.FA, 0.5);
    const RFQ = fluctuate(country.RFQ, 0.5);
    const MD = fluctuate(country.MD, 0.5);
    const KI = fluctuate(country.KI, 0.5);
    const EN = fluctuate(country.EN, 0.5);

    // 2. Fluctuate Global Pillars (Macro Context)
    const EDU = fluctuate(country.EDU, 0.3);
    const INV = fluctuate(country.INV, 0.3);
    const TECH = fluctuate(country.TECH, 0.3);
    const COMP = fluctuate(country.COMP, 0.3);
    const GOV = fluctuate(country.GOV, 0.3);
    const LAW = fluctuate(country.LAW, 0.3);
    const SOC = fluctuate(country.SOC, 0.3);
    const INF_INV = fluctuate(country.INF_INV, 0.3);
    const INF_CRT = fluctuate(country.INF_CRT, 0.3);

    // 3. Recalculate Aggregates
    const IES = calculateIES(RTC, ICT, IAW, PIM, SCW);
    const EEF = calculateEEF(FA, RFQ, MD, KI, EN);
    const SEGRI = calculateSEGRI(IES, EEF);

    // Extended Score Calculation
    const pillarAvg = (EDU + INV + TECH + COMP + GOV + LAW + SOC + INF_INV + INF_CRT) / 9;
    const EXT_SEGRI = (SEGRI * 0.7) + (pillarAvg * 0.3);

    // 4. Update Typology & Quadrant
    const quadrant = determineQuadrant(IES, EEF);
    const typology = determineTypology(RTC, ICT, IAW, PIM, SCW);

    // 5. Fluctuate External Indices
    const GEM = fluctuate(country.GEM, 0.2);
    const B_READY = fluctuate(country.B_READY, 0.2);

    // 6. Fluctuate Ecosystem Counts
    // Startups: Small random drift
    const sVariance = Math.max(2, Math.round(country.startupCount * 0.001));
    const sChange = Math.floor(Math.random() * (sVariance * 2 + 1)) - sVariance;
    const startupCount = Math.max(0, country.startupCount + sChange);

    // Unicorns: Rare changes
    let unicornCount = country.unicornCount;
    if (Math.random() > 0.98) {
        unicornCount = Math.max(0, country.unicornCount + (Math.random() > 0.5 ? 1 : -1));
    }

    return {
      ...country,
      RTC, ICT, IAW, PIM, SCW,
      FA, RFQ, MD, KI, EN,
      EDU, INV, TECH, COMP, GOV, LAW, SOC, INF_INV, INF_CRT,
      IES, EEF, SEGRI, EXT_SEGRI,
      quadrant, typology,
      GEM, B_READY,
      startupCount,
      unicornCount
    } as CountryData;
  });

  return [...liveCountries];
};

export const fetchSectorWeights = async (): Promise<Record<SectorName, SectorRiskWeights>> => {
  await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

  const sectors = Object.keys(liveSectorWeights) as SectorName[];
  sectors.forEach(sector => {
      const w = liveSectorWeights[sector];
      liveSectorWeights[sector] = {
          TRF: fluctuate(w.TRF, 0.01, 0, 1),
          TZR: fluctuate(w.TZR, 0.01, 0, 1),
          JRF: fluctuate(w.JRF, 0.01, 0, 1),
          ESG: fluctuate(w.ESG, 0.01, 0, 1),
          ORF: fluctuate(w.ORF, 0.01, 0, 1),
      };
  });

  return { ...liveSectorWeights };
};

export const fetchGlobalUnicorns = async (): Promise<Unicorn[]> => {
    await new Promise(resolve => setTimeout(resolve, SIMULATED_DELAY));

    // Simulate stock market/valuation volatility
    liveUnicorns = liveUnicorns.map(u => ({
        ...u,
        valuation: fluctuate(u.valuation, 0.1, 1, 500) // Valuations between $1B and $500B
    }));

    return [...liveUnicorns];
}

import { useQuery, UseQueryOptions } from '@tanstack/react-query';
import { fetchCountries, fetchSectorWeights, fetchGlobalUnicorns } from './api';
import { CountryData, Unicorn } from './types';
import { COUNTRY_DATA, SECTOR_WEIGHTS, TOP_UNICORNS } from './constants';

export const QUERY_KEYS = {
  countries: ['countries'] as const,
  sectorWeights: ['sectorWeights'] as const,
  unicorns: ['unicorns'] as const,
};

// Generic hook to fetch all countries with real-time updates
export const useCountries = <T = CountryData[]>(
  options?: Omit<UseQueryOptions<CountryData[], Error, T>, 'queryKey' | 'queryFn' | 'initialData'>
) => {
  return useQuery({
    queryKey: QUERY_KEYS.countries,
    queryFn: fetchCountries,
    initialData: COUNTRY_DATA,
    refetchInterval: 3000, // Sync every 3 seconds
    staleTime: 1000,
    refetchOnWindowFocus: true,
    structuralSharing: true,
    ...options,
  });
};

export const useCountry = (code: string) => {
  return useCountries<CountryData | undefined>({
    select: (data) => data.find((c) => c.code === code),
    enabled: !!code,
  });
};

export const useSectorWeights = () => {
  return useQuery({
    queryKey: QUERY_KEYS.sectorWeights,
    queryFn: fetchSectorWeights,
    initialData: SECTOR_WEIGHTS,
    refetchInterval: 5000, // Sync every 5 seconds
    staleTime: 2000,
    refetchOnWindowFocus: true,
  });
};

export const useGlobalUnicorns = () => {
    return useQuery({
        queryKey: QUERY_KEYS.unicorns,
        queryFn: fetchGlobalUnicorns,
        initialData: TOP_UNICORNS,
        refetchInterval: 10000, // Valuations update every 10 seconds
        staleTime: 5000,
        refetchOnWindowFocus: true,
    });
};

